window.YC_MORE_QBANKS=window.YC_MORE_QBANKS||[];window.YC_MORE_QBANKS.push([{"module":"yiliao","prompt":"人体全身的骨共多少块？","options":["206","208","204","210"],"answer":0,"explanation":"成人全身骨共206块（含6块听小骨）。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1001","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"人体最长的骨是？","options":["股骨","胫骨","肱骨","腓骨"],"answer":0,"explanation":"股骨是人体最长的长骨，约占身高的27%。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1002","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"脊柱成人由多少块椎骨组成？","options":["32块","24块","26块","33块"],"answer":2,"explanation":"成人脊柱由24块椎骨、1块骶骨、1块尾骨共26块组成；幼儿骶尾未融合时为33块。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1003","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"颈椎的特征性结构是？","options":["横突孔","肋凹","齿突隆起","耳状面"],"answer":0,"explanation":"颈椎横突有横突孔，内有椎动、静脉通过，是颈椎的特征。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1004","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"椎间盘由哪两部分构成？","options":["椎体和椎弓","前纵韧带和后纵韧带","纤维环和髓核","黄韧带和棘上韧带"],"answer":2,"explanation":"椎间盘中央为髓核，周围为纤维环，连接相邻椎体。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1005","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"髓核突出的方向是？","options":["向上方","向前方","向侧方","向后外方"],"answer":3,"explanation":"纤维环后外侧薄弱，髓核多向后外方突出，压迫神经根。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1006","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"胸廓参与呼吸的主要肌是？","options":["斜方肌","胸锁乳突肌","膈和肋间肌","前锯肌"],"answer":2,"explanation":"平静呼吸时膈和肋间外肌是主要呼吸肌。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1007","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"膈的主动脉裂孔位置约平？","options":["第10胸椎","第8胸椎","第12胸椎","第6颈椎"],"answer":2,"explanation":"膈有三个裂孔：主动脉裂孔平第12胸椎，食管裂孔平第10胸椎，腔静脉孔平第8胸椎。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1008","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肩关节的结构特点是？","options":["肱骨头大、关节盂浅，灵活性大","关节囊厚而坚韧","有关节盘","稳定性大于灵活性"],"answer":0,"explanation":"肩关节盂浅头大、囊松弛，是全身最灵活的关节，但稳定性差易脱位。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1009","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肘关节不包括？","options":["桡腕关节","肱尺关节","肱桡关节","桡尺近侧关节"],"answer":0,"explanation":"肘关节由肱尺、肱桡、桡尺近侧三组关节构成；桡腕关节属腕部。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1010","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"髋关节与肩关节相比，其特点是？","options":["稳定性大、灵活性小","灵活性大、稳定性小","均有关节盘","均无韧带"],"answer":0,"explanation":"髋关节头深盂深、韧带强大，稳定性大而灵活性小于肩关节。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1011","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"膝关节内的重要结构是？","options":["三角韧带","关节盂唇","喙肩韧带","半月板和交叉韧带"],"answer":3,"explanation":"膝关节内有内、外侧半月板和前、后交叉韧带。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1012","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"前交叉韧带断裂时胫骨出现？","options":["向内移位","向后移位","向外移位","向前移位"],"answer":3,"explanation":"前交叉韧带防止胫骨前移，断裂后抽屉试验胫骨前移阳性。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1013","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"足弓的功能主要是？","options":["产生红细胞","分泌滑液","缓冲震荡和保护血管神经","传导痛觉"],"answer":2,"explanation":"足弓弹性结构可缓冲行走震荡，保护足底血管神经。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1014","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"颅底内面由前向后的颅窝顺序是？","options":["颅前窝、颅中窝、颅后窝","颅后窝、颅中窝、颅前窝","颅中窝、颅前窝、颅后窝","颅前窝、颅后窝、颅中窝"],"answer":0,"explanation":"颅底内面从前向后为颅前、中、后三个颅窝，位置逐渐降低。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1015","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"脑颅骨共几块？","options":["8块","6块","12块","14块"],"answer":0,"explanation":"脑颅骨8块（额、筛、蝶、枕各1，颞、顶各2）；面颅骨15块。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1016","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"乳突属于哪块骨的结构？","options":["枕骨","颞骨","顶骨","蝶骨"],"answer":1,"explanation":"乳突是颞骨后下方的骨性突起，胸锁乳突肌附着处。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1017","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"翼点位于？","options":["枕骨","眶下","颞窝","鼻中隔"],"answer":2,"explanation":"翼点是额、顶、颞、蝶四骨汇合处的H形缝，骨质薄弱，内面有脑膜中动脉前支。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1018","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"上颌窦的开口位于？","options":["鼻泪管","上鼻道","下鼻道","中鼻道"],"answer":3,"explanation":"上颌窦开口于中鼻道，位置高引流不畅，易发炎。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1019","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"计数肋骨的重要体表标志是？","options":["锁骨","胸骨下角","剑突","胸骨角"],"answer":3,"explanation":"胸骨角平第2肋，是计数肋和肋间隙的标志。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1020","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肱骨外科颈骨折易损伤？","options":["正中神经","桡神经","腋神经","尺神经"],"answer":2,"explanation":"腋神经绕肱骨外科颈走行，骨折易损伤致三角肌瘫痪。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1021","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肱骨中段骨折易损伤？","options":["胸背神经","腋神经","肌皮神经","桡神经"],"answer":3,"explanation":"桡神经沿桡神经沟绕肱骨中段走行，骨折易损伤致垂腕。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1022","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"腓骨颈骨折易损伤？","options":["闭孔神经","胫神经","股神经","腓总神经"],"answer":3,"explanation":"腓总神经绕腓骨颈走行，位置表浅易损伤致足下垂。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1023","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"关节的基本结构不包括？","options":["关节面","关节唇","关节囊","关节腔"],"answer":1,"explanation":"关节基本结构为关节面、囊、腔；关节唇属辅助结构。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1024","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"滑膜关节的辅助结构不包括？","options":["韧带","关节软骨","关节盘","滑膜襞"],"answer":1,"explanation":"关节软骨属基本结构（关节面上的软骨）；韧带、盘、唇、滑膜襞为辅助结构。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1025","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"脊柱的生理性弯曲有几个？","options":["4个","3个","2个","5个"],"answer":0,"explanation":"脊柱有颈、胸、腰、骶4个生理弯曲，颈腰凸向前、胸骶凸向后。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1026","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"胸椎的特征性结构是？","options":["翼点","横突孔","乳突","肋凹"],"answer":3,"explanation":"胸椎椎体两侧和横突有肋凹，与肋骨相关节。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1027","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"腰椎穿刺常选择的间隙是？","options":["第3、4腰椎间","第1、2腰椎间","第5腰椎与骶椎间","第12胸椎与第1腰椎间"],"answer":0,"explanation":"成人脊髓止于第1腰椎下缘，第3、4腰椎间穿刺可避开脊髓。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1028","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肩胛骨下角平对？","options":["第9肋","第5肋","第7肋","第3肋"],"answer":2,"explanation":"肩胛骨下角平第7肋或第7肋间隙，是背部计数肋的标志。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1029","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"桡神经沟位于？","options":["肩胛骨","尺骨","桡骨","肱骨"],"answer":3,"explanation":"桡神经沟是肱骨体后面的一条斜行浅沟。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1030","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"人体最大的籽骨是？","options":["距骨","豌豆骨","跟骨","髌骨"],"answer":3,"explanation":"髌骨是全身最大的籽骨，包于股四头肌腱内。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1031","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"跟骨属于？","options":["籽骨","跖骨","趾骨","跗骨"],"answer":3,"explanation":"跗骨7块：跟、距、足舟、骰及3块楔骨；跟骨最大。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1032","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"距骨上方与什么骨构成踝关节？","options":["足舟骨","跟骨","胫腓骨下端","股骨"],"answer":2,"explanation":"踝关节由胫腓骨下端与距骨滑车构成。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1033","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"胸锁乳突肌的作用是？","options":["仅使头后仰","使头向同侧倾斜、面转向对侧","上提肋助吸气","外展肩关节"],"answer":1,"explanation":"单侧收缩使头向同侧倾、面转向对侧；双侧收缩使头后仰。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1034","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"股四头肌的作用是？","options":["伸膝关节","屈膝关节","外展髋关节","内收髋关节"],"answer":0,"explanation":"股四头肌是全身最大的肌，主要作用为伸膝关节。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1035","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"小腿三头肌由什么组成？","options":["股二头肌和半腱肌","胫骨前肌和趾长伸肌","腓骨长肌和短肌","腓肠肌和比目鱼肌"],"answer":3,"explanation":"小腿三头肌=腓肠肌+比目鱼肌，会合为跟腱。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1036","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"三角肌瘫痪时肩部表现是？","options":["足下垂","翼状肩","垂腕","方肩"],"answer":3,"explanation":"三角肌萎缩失去圆隆外形称方肩，常见于腋神经损伤。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1037","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"膈收缩时胸廓容积？","options":["先大后小","减小，助呼气","不变","增大，助吸气"],"answer":3,"explanation":"膈收缩穹隆下降，胸腔容积增大，是主要吸气肌。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1038","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"腹股沟管的内口是？","options":["腹股沟管浅环","腹股沟管深环","股环","海氏三角"],"answer":1,"explanation":"腹股沟管内口为深环（腹环），外口为浅环（皮下环）。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1039","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"斜方肌瘫痪时出现？","options":["垂腕","方肩","翼状肩胛","塌肩"],"answer":3,"explanation":"斜方肌上提肩胛骨，瘫痪后肩部下垂称塌肩。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1040","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"上消化道与下消化道的分界是？","options":["幽门","食管胃连接部","回盲部","十二指肠空肠曲"],"answer":3,"explanation":"临床上以十二指肠空肠曲（Treitz韧带）为上下消化道分界。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1041","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"咽峡的构成不包括？","options":["腭舌弓","腭垂（悬雍垂）","舌根","腭咽弓"],"answer":1,"explanation":"咽峡由腭垂、腭舌弓、舌根等围成，是口与咽的分界。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1042","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"牙的构造中，暴露在口腔的部分是？","options":["牙髓","牙根","牙颈","牙冠"],"answer":3,"explanation":"牙分冠、颈、根三部，冠暴露于口腔。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1043","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"乳牙共多少颗？","options":["32颗","28颗","20颗","24颗"],"answer":2,"explanation":"乳牙20颗，恒牙28~32颗（含第三磨牙）。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1044","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"腮腺导管开口于？","options":["舌下阜","上颌第2磨牙相对的颊黏膜","舌下襞","下颌第2磨牙相对处"],"answer":1,"explanation":"腮腺导管开口于上颌第2磨牙相对的颊黏膜处。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1045","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"下颌下腺开口于？","options":["舌下襞","舌下阜","中鼻道","颊黏膜"],"answer":1,"explanation":"下颌下腺和舌下腺大管开口于舌下阜。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1046","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"食管的三处生理性狭窄不包括？","options":["与左主支气管交叉处","咽与食管移行处","食管胃连接处","穿膈肌食管裂孔处"],"answer":2,"explanation":"食管三狭窄：起始部、与左主支气管交叉处、穿膈处；食管胃连接处不属生理狭窄。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1047","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"食管第三个狭窄距中切牙约？","options":["55cm","25cm","15cm","40cm"],"answer":3,"explanation":"食管全长约25cm，三狭窄距中切牙约15、25、40cm。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1048","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"胃的分部不包括？","options":["贲门部","胃底","胃体","胃小弯"],"answer":2,"explanation":"胃分贲门部、胃底、胃体、幽门部四部；胃小弯是边缘不是分部。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1049","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"胃溃疡和十二指肠溃疡的好发部位分别是？","options":["幽门部胃小弯、十二指肠球部","胃底、降部","贲门部、水平部","胃大弯、升部"],"answer":0,"explanation":"胃溃疡好发幽门部胃小弯，十二指肠溃疡好发球部（前壁）。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1050","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"十二指肠大乳头位于？","options":["球部","降部","水平部","升部"],"answer":1,"explanation":"胆总管和胰管共同开口于十二指肠降部的十二指肠大乳头。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1051","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"十二指肠溃疡好发部位是？","options":["降部","球部","水平部","升部"],"answer":1,"explanation":"十二指肠球部（上部）是溃疡最好发部位。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1052","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"小肠中最长的一段是？","options":["回肠","空肠","十二指肠","盲肠"],"answer":1,"explanation":"空肠与回肠合称系膜小肠，空肠占近侧2/5、回肠占远侧3/5，回肠更长。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1053","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"小肠内环状皱襞最发达的部位是？","options":["十二指肠球部","回肠末端","十二指肠和空肠上段","空肠下段"],"answer":2,"explanation":"环状皱襞在十二指肠末段和空肠上段最发达，利于吸收。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1054","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"大肠的特征性结构不包括？","options":["绒毛","结肠带","结肠袋","肠脂垂"],"answer":0,"explanation":"结肠带、结肠袋、肠脂垂是大肠三大特征；绒毛是小肠结构。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1055","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"阑尾根部的体表投影是？","options":["McBurney点","Murphy点","Koch点","Lanz点"],"answer":0,"explanation":"阑尾根投影于脐与右髂前上棘连线中外1/3交界处（麦氏点）。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1056","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"阑尾手术寻找阑尾的可靠标志是？","options":["结肠袋","结肠带","肠脂垂","回盲瓣"],"answer":1,"explanation":"三条结肠带汇合于阑尾根部，是术中寻找阑尾的标志。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1057","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肝的位置大部分位于？","options":["左季肋区","右季肋区和腹上区","右腰区","脐区"],"answer":1,"explanation":"肝大部分位于右季肋区和腹上区，小部分位于左季肋区。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1058","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肝门的结构不包括？","options":["肝管","肝门静脉","肝固有动脉","肝静脉"],"answer":3,"explanation":"肝门有肝门静脉、肝固有动脉、肝管等出入；肝静脉自肝后缘出肝注入下腔静脉。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1059","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"胆囊位于？","options":["肝左叶","肝右叶下面的胆囊窝内","十二指肠降部","胃小弯"],"answer":1,"explanation":"胆囊位于肝右叶脏面的胆囊窝内。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1060","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"胆囊底的体表投影是？","options":["左锁骨中线与肋弓交点","右锁骨中线与右肋弓交点附近","脐与右髂前上棘连线中点","剑突下"],"answer":1,"explanation":"胆囊底投影于右锁骨中线（或右腹直肌外缘）与右肋弓交点处，胆囊炎压痛点。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1061","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"胆总管由什么汇合而成？","options":["胆囊管与胰管","左右肝管","肝总管与胰管","肝总管与胆囊管"],"answer":3,"explanation":"左、右肝管汇成肝总管，肝总管与胆囊管汇成胆总管。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1062","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"胆总管与胰管共同开口于？","options":["十二指肠球部","十二指肠大乳头","十二指肠空肠曲","幽门"],"answer":1,"explanation":"两者汇合成肝胰壶腹，开口于十二指肠降部大乳头。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1063","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"胰的位置横过？","options":["骶岬前方","第3、4腰椎前方","第12胸椎前方","第1、2腰椎前方"],"answer":3,"explanation":"胰横位于腹后壁，平第1、2腰椎，横过脊柱前方。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1064","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"腹膜外位器官是？","options":["肝","胃","空肠","肾"],"answer":3,"explanation":"肾、输尿管、肾上腺、胰等为腹膜外位（后位）器官。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1065","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"腹膜内位器官是？","options":["胰","肾","空肠","膀胱"],"answer":2,"explanation":"空回肠、胃、阑尾等表面几乎全被腹膜覆盖，为内位器官。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1066","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"小网膜的组成是？","options":["肝胃韧带和肝十二指肠韧带","胃结肠韧带","膈结肠韧带","镰状韧带"],"answer":0,"explanation":"小网膜=肝胃韧带+肝十二指肠韧带（内含胆总管、肝固有动脉、门静脉）。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1067","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"直肠的两个弯曲方向是？","options":["骶曲凸向前、会阴曲凸向后","均凸向后","均凸向前","骶曲凸向后、会阴曲凸向前"],"answer":3,"explanation":"直肠骶曲凸向后（贴骶骨），会阴曲凸向前。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1068","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肛管的齿状线由什么构成？","options":["肛门外括约肌","白线","肛柱下端与肛瓣边缘连线","痔环"],"answer":2,"explanation":"齿状线是肛柱下端与肛瓣边缘的锯齿状连线，是黏膜与皮肤分界。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1069","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"齿状线上下结构的差异不包括？","options":["淋巴引流不同","动脉供应来源不同","静脉回流方向不同","神经支配均为躯体神经"],"answer":3,"explanation":"齿状线以上为内脏神经（无痛觉），以下为躯体神经（痛觉敏感）；其余均不同。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1070","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肝门静脉的属支不包括？","options":["肠系膜上静脉","肝静脉","脾静脉","胃左静脉"],"answer":1,"explanation":"肝静脉注入下腔静脉，不属门静脉属支。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1071","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肝门静脉高压时侧支循环不经过？","options":["食管静脉丛","下腔静脉-肾静脉吻合","直肠静脉丛","脐周静脉网"],"answer":1,"explanation":"门脉高压侧支循环：食管胃底静脉丛、直肠静脉丛、脐周静脉网、腹膜后静脉丛；不经肾静脉。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1072","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"乳糜池位于？","options":["第1腰椎前方","第12胸椎前方","第2骶椎前方","第5腰椎前方"],"answer":0,"explanation":"乳糜池是胸导管起始部的膨大，位于第1腰椎（膈肌主动脉裂孔）前方。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1073","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"咽的分部不包括？","options":["口咽","鼻咽","咽隐窝部","喉咽"],"answer":2,"explanation":"咽分鼻咽、口咽、喉咽三部；咽隐窝是鼻咽部的结构。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1074","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"鼻咽癌的好发部位是？","options":["扁桃体窝","咽隐窝","梨状隐窝","蝶筛隐窝"],"answer":1,"explanation":"咽隐窝是鼻咽癌好发部位，位于鼻咽侧壁。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1075","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"上呼吸道包括？","options":["鼻、咽、喉","鼻、咽、气管","喉、气管、支气管","鼻、喉、支气管"],"answer":0,"explanation":"上呼吸道为鼻、咽、喉；气管及以下为下呼吸道。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1076","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"鼻旁窦不包括？","options":["蝶窦","筛窦","上颌窦","乳突窦"],"answer":0,"explanation":"鼻旁窦4对：额、筛、蝶、上颌窦；乳突窦属中耳。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1077","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"开口于上鼻道的鼻旁窦是？","options":["额窦","上颌窦","筛窦后群","筛窦前群"],"answer":2,"explanation":"上鼻道引流筛窦后群；中鼻道引流上颌窦、额窦、筛窦前中群。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1078","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"鼻出血的好发部位是？","options":["中鼻道","鼻中隔后部","下鼻道","鼻中隔前下部（Little区）"],"answer":3,"explanation":"鼻中隔前下部血管丰富表浅，称易出血区。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1079","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"喉软骨中不成对的是？","options":["只有甲状软骨","杓状软骨","只有环状软骨","甲状软骨、环状软骨、会厌软骨"],"answer":3,"explanation":"喉软骨3块不成对（甲状、环状、会厌），成对1块（杓状）。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1080","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"喉腔中最狭窄的部位是？","options":["前庭裂","声门裂","喉口","声门下腔"],"answer":1,"explanation":"声门裂是两侧声襞之间的裂隙，为喉腔最窄处。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1081","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"环甲膜穿刺的定位依据是？","options":["甲状软骨与环状软骨之间","环状软骨与气管之间","舌骨与甲状软骨之间","第2、3气管软骨之间"],"answer":0,"explanation":"环甲膜位于甲状软骨下缘与环状软骨上缘之间，是紧急通气的穿刺部位。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1082","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"婴幼儿喉腔炎症易致喉梗阻的原因是？","options":["喉腔狭窄固定","声门裂宽大","软骨已钙化","声门下腔黏膜疏松、组织软弱"],"answer":3,"explanation":"婴幼儿声门下腔黏膜下组织疏松，炎症时易肿胀致喉梗阻。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1083","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"气管软骨环的数目约为？","options":["10个","6~8个","20~24个","14~16个"],"answer":3,"explanation":"气管由14~16个C形软骨环构成，缺口向后。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1084","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"右主支气管的特点是？","options":["粗、短、直","细、长、斜","与左主支气管相同","走行水平"],"answer":0,"explanation":"右主支气管粗短陡直，气管异物多坠入右主支气管。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1085","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肺尖的位置超出？","options":["锁骨内侧1/3上方2~3cm","锁骨外侧1/3上方","胸廓上口以下","第1肋以下"],"answer":0,"explanation":"肺尖高出锁骨内侧1/3上方2~3cm。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1086","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"左肺的分叶是？","options":["2叶（上、下）","3叶（上、中、下）","4叶","1叶"],"answer":0,"explanation":"左肺2叶（有心切迹），右肺3叶。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1087","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肺门的结构不包括？","options":["主支气管","肺动脉","肺静脉","肺韧带"],"answer":3,"explanation":"肺门有主支气管、肺动静脉、支气管动静脉、淋巴管神经；肺韧带是胸膜结构。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1088","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肋膈隐窝（肋膈窦）的临床意义是？","options":["气体常积聚处","胸腔积液常积聚处","心包积液处","肺气肿好发处"],"answer":1,"explanation":"肋膈隐窝是胸膜腔最低处，积液常积聚，是穿刺抽液部位。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1089","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"胸膜腔负压的生理意义不包括？","options":["促进静脉血回流","维持肺的扩张状态","促进淋巴回流","使肺泡壁变厚"],"answer":1,"explanation":"胸内负压维持肺扩张、促进静脉淋巴回流；不使肺泡壁变厚。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1090","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肺泡隔内的吞噬细胞是？","options":[" Clara细胞","杯状细胞","尘细胞","嗜银细胞"],"answer":2,"explanation":"肺泡隔内的巨噬细胞吞噬尘粒后称尘细胞。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1091","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"气血屏障的组成不包括？","options":["胸膜脏层","肺泡上皮细胞","基膜","肺泡壁毛细血管内皮细胞"],"answer":3,"explanation":"气血屏障=肺泡上皮+基膜+毛细血管内皮（含融合基膜），不含胸膜。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1092","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"呼吸道的屏障结构不包括？","options":["黏液毯","鼻毛","纤毛","肺泡Ⅰ型上皮细胞"],"answer":3,"explanation":"Ⅰ型细胞主要行气体交换；鼻毛、纤毛、黏液、咳嗽反射属屏障防御。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1093","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"气管切开常选择的部位是？","options":["第1~2气管软骨环处","第3~5气管软骨环处","第6~8气管软骨环处","环甲膜处"],"answer":1,"explanation":"气管切开选颈段第3~5气管软骨环。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1094","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"胸膜腔穿刺抽液常选？","options":["锁骨中线第2肋间抽液","肩胛线第7~8肋间（腋后线）","胸骨旁第4肋间","腋前线第5肋间"],"answer":1,"explanation":"胸腔积液穿刺常选肩胛线或腋后线第7~8肋间；气胸穿刺在锁骨中线第2肋间。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1095","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"气胸穿刺排气常选？","options":["胸骨左缘第4肋间","肩胛线第7~8肋间","腋中线第8肋间","锁骨中线第2肋间"],"answer":3,"explanation":"胸腔积气上浮，常在锁骨中线第2肋间穿刺。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1096","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肺下界的体表投影在锁骨中线处平？","options":["第8肋","第6肋","第4肋","第10肋"],"answer":1,"explanation":"肺下界：锁骨中线平第6肋、腋中线平第8肋、肩胛线平第10肋；胸膜下界比肺下界低2肋。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1097","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"胸膜下界在腋中线处平？","options":["第12肋","第6肋","第10肋","第8肋"],"answer":3,"explanation":"胸膜下界比肺下界约低2个肋：锁骨中线第8肋、腋中线第10肋、肩胛线第12肋。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1098","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肺的有效气体交换面积约为？","options":["70~100m²","10~20m²","150~200m²","5~10m²"],"answer":0,"explanation":"成人肺泡约3~4亿个，总交换面积约70~100m²。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1099","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"支气管树中气体交换开始于？","options":["呼吸性细支气管","终末细支气管","段支气管","小支气管"],"answer":0,"explanation":"终末细支气管以上仅通气；呼吸性细支气管开始有气体交换功能。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1100","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肺的传导部（导气部）止于？","options":["呼吸性细支气管","终末细支气管","肺泡管","肺泡囊"],"answer":1,"explanation":"导气部从支气管到终末细支气管；呼吸性细支气管起为呼吸部。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1101","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"纵隔的分区常以什么为界？","options":["主动脉弓平面","气管分叉平面","胸骨角与第4胸椎下缘平面","肺门平面"],"answer":2,"explanation":"纵隔以胸骨角平面（平第4胸椎下缘）分上、下纵隔。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1102","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"心位于纵隔的？","options":["中纵隔","上纵隔","前纵隔","后纵隔"],"answer":0,"explanation":"心包、心位于中纵隔；胸腺位于前上纵隔。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1103","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肺循环的特点是？","options":["与体循环压力相同","路径长、压力高","路径短、压力低","只供应肺组织营养"],"answer":2,"explanation":"肺循环路径短、阻力低、压力低，为低压系统。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1104","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"呼吸系统的防御功能不包括？","options":["分泌IgA","咳嗽反射","纤毛运动","产生胃酸"],"answer":3,"explanation":"胃酸属消化系统；呼吸道防御有咳嗽反射、纤毛、黏液、分泌型IgA等。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1105","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肾的位置约平？","options":["第9~11胸椎","第1~3腰椎","第11胸椎至第2腰椎","第3~5腰椎"],"answer":2,"explanation":"肾随呼吸上下移动，约平第11胸椎至第2~3腰椎，右肾略低。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1106","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"右肾略低于左肾的原因是？","options":["受肝的影响","受脾的影响","受胃的影响","受胰的影响"],"answer":0,"explanation":"肝位于右肾上方，将右肾推低约半个椎体。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1107","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肾的结构单位是？","options":["肾盂","肾小盏","肾单位","集合管"],"answer":2,"explanation":"肾单位是肾结构与功能的基本单位，每侧约100万个。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1108","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"每侧肾的肾单位约有多少个？","options":["10万个","100万个","500万个","1000万个"],"answer":1,"explanation":"每侧肾约100万（100~150万）个肾单位。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1109","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肾单位的组成是？","options":["肾小体和肾小管","肾小球和肾小囊","肾小管和集合管","肾小盏和肾盂"],"answer":0,"explanation":"肾单位=肾小体（小球+小囊）+肾小管。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1110","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肾小体的组成是？","options":["血管球和肾小囊","肾小球和肾小管","肾小管和集合管","近曲小管和远曲小管"],"answer":0,"explanation":"肾小体由血管球（毛细血管球）和肾小囊构成。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1111","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"滤过膜的组成不包括？","options":["肾小管上皮","有孔内皮","基膜","足细胞裂孔膜"],"answer":0,"explanation":"滤过膜=毛细血管有孔内皮+基膜+肾小囊脏层足细胞裂孔膜；不含肾小管上皮。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1112","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肾小管的重吸收主要发生在？","options":["远曲小管","近曲小管","髓袢","集合管"],"answer":1,"explanation":"近曲小管重吸收原尿中约65%~70%的水和绝大部分营养物质。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1113","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"原尿中绝大部分营养物质重吸收的部位是？","options":["集合管","髓袢细段","远端小管","近端小管"],"answer":3,"explanation":"葡萄糖、氨基酸等几乎全部在近端小管重吸收。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1114","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"尿液生成的调节不包括？","options":["抗利尿激素","大脑皮层直接重吸收原尿","醛固酮","交感神经"],"answer":1,"explanation":"ADH调节水重吸收、醛固酮保钠排钾、交感调节血流；皮层不直接重吸收。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1115","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"输尿管的三个狭窄不包括？","options":["膀胱三角区","肾盂与输尿管移行处","跨髂血管处","穿膀胱壁处"],"answer":0,"explanation":"输尿管三狭窄：起始部、跨髂血管处、壁内段；膀胱三角不是输尿管狭窄。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1116","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"输尿管结石易滞留的部位是？","options":["三个生理性狭窄处","输尿管中段","肾盂内","膀胱内"],"answer":0,"explanation":"结石易在狭窄处嵌顿，引起绞痛。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1117","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"膀胱三角位于？","options":["膀胱体前壁","膀胱尖","膀胱底内面","尿道内口周围"],"answer":2,"explanation":"膀胱三角=两输尿管口与尿道内口之间的三角形区域，黏膜平滑无皱襞。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1118","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"膀胱三角的特点是？","options":["黏膜多皱襞","黏膜平滑无皱襞","有大量腺体","壁最薄易穿孔"],"answer":1,"explanation":"三角区黏膜平滑无皱襞，是肿瘤和结核好发部位。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1119","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"膀胱充盈时，成人正常容量约？","options":["300~500ml","100~200ml","1000ml以上","50~100ml"],"answer":0,"explanation":"成人膀胱正常充盈容量约300~500ml。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1120","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"女性尿道的特点是？","options":["与男性相同","细长弯曲","短、直、宽，易感染","开口于阴道前庭后部"],"answer":2,"explanation":"女性尿道长约3~5cm，短直宽，易发生逆行尿路感染。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1121","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"男性尿道最狭窄处是？","options":["尿道外口","尿道内口","膜部","前列腺部"],"answer":0,"explanation":"男性尿道三狭窄：内口、膜部、外口；最窄为外口，膜部最短。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1122","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"男性尿道的分部不包括？","options":["尿道球腺部","前列腺部","膜部","海绵体部"],"answer":0,"explanation":"男性尿道分前列腺部、膜部、海绵体部三部；无球腺部。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1123","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"男性尿道最短的部位是？","options":["海绵体部","前列腺部","膜部","舟状窝"],"answer":2,"explanation":"膜部长约1.2cm，是三部中最短者。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1124","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肾的被膜由内向外依次是？","options":["肾筋膜、脂肪囊、纤维囊","纤维囊、脂肪囊、肾筋膜","脂肪囊、纤维囊、肾筋膜","纤维囊、肾筋膜、脂肪囊"],"answer":1,"explanation":"肾被膜三层由内向外：纤维囊、脂肪囊（肾周脂肪）、肾筋膜。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1125","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肾蒂主要结构的排列从前向后是？","options":["肾静脉、肾动脉、肾盂","肾动脉、肾静脉、肾盂","肾盂、肾动脉、肾静脉","肾动脉、肾盂、肾静脉"],"answer":0,"explanation":"肾蒂由前向后：静脉、动脉、肾盂；由上向下：动脉、静脉、肾盂。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1126","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肾的固定因素不包括？","options":["邻近器官","肾筋膜","脂肪囊","肾小球的滤过压"],"answer":3,"explanation":"肾靠被膜、血管、腹压及邻近器官固定；滤过压与位置无关。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1127","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肾盂结石排出时最易嵌顿于？","options":["肾盏","输尿管三个狭窄处","膀胱三角","尿道海绵体部"],"answer":1,"explanation":"狭窄处管腔小，结石易嵌顿。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1128","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肾小球滤过率正常成人约为？","options":["500ml/min","50ml/min","300ml/min","125ml/min"],"answer":3,"explanation":"正常成人GFR约125ml/min（100~150ml/min）。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1129","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"正常成人24小时尿量约？","options":["200~400ml","500~800ml","3000~4000ml","1000~2000ml"],"answer":3,"explanation":"24h尿量1000~2000ml；<400ml为少尿，>2500ml为多尿。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1130","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"少尿是指24小时尿量少于？","options":["100ml","400ml","500ml","1000ml"],"answer":1,"explanation":"24h尿量<400ml（或每小时<17ml）为少尿；<100ml为无尿。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1131","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"无尿是指24小时尿量少于？","options":["100ml","400ml","50ml","200ml"],"answer":0,"explanation":"24h尿量<100ml为无尿，提示肾功能严重受损。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1132","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"多尿是指24小时尿量超过？","options":["3000ml","1500ml","2500ml","2000ml"],"answer":2,"explanation":"24h尿量>2500ml为多尿。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1133","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"排尿反射的初级中枢位于？","options":["脑桥","延髓","骶髓","下丘脑"],"answer":2,"explanation":"排尿反射初级中枢在骶髓（第2~4骶节），高级中枢在大脑皮层。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1134","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肾小球有效滤过压的组成不包括？","options":["肾小球毛细血管血压","血浆胶体渗透压的促进成分","血浆胶体渗透压","肾小囊内压"],"answer":1,"explanation":"有效滤过压=毛细血管血压−（血浆胶体渗透压+囊内压）；胶体渗透压是阻力不是动力。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1135","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"男性生殖腺是？","options":["附睾","睾丸","前列腺","精囊"],"answer":1,"explanation":"睾丸产生精子并分泌雄激素，是男性生殖腺。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1136","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"精子产生的部位是？","options":["附睾管","生精小管","输精管","前列腺"],"answer":1,"explanation":"精子在睾丸生精小管产生，经附睾成熟储存。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1137","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"男性结扎常用的部位是？","options":["输精管","附睾","射精管","尿道"],"answer":0,"explanation":"输精管结扎是男性绝育常用术式。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1138","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"前列腺的位置是？","options":["膀胱与尿生殖膈之间","精囊上方","耻骨联合前方","直肠前方"],"answer":0,"explanation":"前列腺位于膀胱颈与尿生殖膈之间，包绕尿道前列腺部。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1139","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"前列腺增生压迫的结构是？","options":["射精管","尿道膜部","尿道前列腺部","膀胱三角"],"answer":2,"explanation":"前列腺中叶增生压迫尿道前列腺部，致排尿困难。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1140","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"男性直肠指检不能触及的结构是？","options":["输精管壶腹以外的输精管","前列腺","精囊","膀胱底"],"answer":0,"explanation":"直肠指检可触及前列腺、精囊、膀胱底及输精管壶腹；不能触及输精管其他段。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1141","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"女性生殖腺是？","options":["子宫","输卵管","卵巢","阴道"],"answer":2,"explanation":"卵巢产生卵子并分泌女性激素。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1142","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"卵子受精的常见部位是？","options":["输卵管壶腹部","输卵管峡部","子宫腔","输卵管漏斗部"],"answer":0,"explanation":"受精多发生在输卵管壶腹部。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1143","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"输卵管结扎常用的部位是？","options":["输卵管峡部","壶腹部","漏斗部","子宫部"],"answer":0,"explanation":"峡部管腔窄、血管少，是结扎常用部位。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1144","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"宫外孕最常见的发生部位是？","options":["输卵管壶腹部","卵巢","腹腔","宫颈"],"answer":0,"explanation":"异位妊娠以输卵管妊娠最常见，其中壶腹部最多。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1145","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"子宫的位置是？","options":["膀胱与直肠之间","膀胱前上方","直肠后","盆腔中央偏后"],"answer":0,"explanation":"子宫位于小骨盆中央、膀胱与直肠之间，呈前倾前屈位。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1146","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"维持子宫前倾的主要韧带是？","options":["骶子宫韧带","子宫阔韧带","子宫主韧带","子宫圆韧带"],"answer":3,"explanation":"圆韧带维持前倾，骶子宫韧带维持前屈，主韧带防下垂。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1147","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"防止子宫脱垂的主要结构是？","options":["卵巢悬韧带","子宫圆韧带","子宫主韧带和盆底肌","子宫阔韧带"],"answer":2,"explanation":"主韧带（子宫颈横韧带）固定子宫颈，与盆膈共同防脱垂。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1148","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"子宫颈癌的好发部位是？","options":["宫底","子宫体","宫颈管内口","子宫颈鳞状上皮与柱状上皮交界处"],"answer":3,"explanation":"鳞柱交界处（宫颈外口）是好发部位。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1149","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"月经周期中子宫内膜功能层的变化顺序是？","options":["月经期、增生期、分泌期","增生期、分泌期、月经期","分泌期、月经期、增生期","月经期、分泌期、增生期"],"answer":1,"explanation":"月经周期（以28天计）：月经期→增生期→分泌期。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1150","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"排卵一般发生在月经周期的？","options":["下次月经前14天左右","月经第1天","月经第7天","月经第28天"],"answer":0,"explanation":"排卵日约在下次月经来潮前14天。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1151","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"排卵后形成黄体，若未受精，黄体维持约？","options":["3天","7天","28天","14天"],"answer":3,"explanation":"未受精黄体维持约14天后退化（月经黄体）。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1152","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"阴道穹最深的部位是？","options":["后部","前部","左侧部","右侧部"],"answer":0,"explanation":"后穹窿最深，与直肠子宫陷凹相邻，可穿刺。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1153","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"乳房脓肿切开引流常选？","options":["放射状切口","横切口","纵切口","弧形切口"],"answer":0,"explanation":"放射状切口减少损伤输乳管。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1154","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"会阴是指？","options":["阴道前庭","仅指外生殖器","仅指肛门区","广义为盆膈以下封闭骨盆下口的全部软组织"],"answer":3,"explanation":"广义会阴为封闭骨盆下口的全部软组织；狭义为阴道口与肛门之间的区域。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1155","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"心脏的位置位于？","options":["上纵隔","前纵隔","后纵隔","中纵隔"],"answer":3,"explanation":"心位于中纵隔，2/3偏左侧。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1156","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"心的体表投影心尖指向？","options":["左锁骨中线第5肋间内0.5~1cm","右锁骨中线第4肋间","胸骨左缘第3肋间","左腋中线第6肋"],"answer":0,"explanation":"心尖由左心室构成，投影于左锁骨中线与第5肋间交点内0.5~1cm。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1157","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"心尖的搏动点在？","options":["左侧第5肋间锁骨中线内0.5~1cm","右侧第5肋间","胸骨角平面","剑突下"],"answer":0,"explanation":"心尖搏动即左室心尖投影处。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1158","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"心脏的传导系统不包括？","options":["房室结","窦房结","迷走神经","浦肯野纤维"],"answer":2,"explanation":"传导系统由特殊心肌细胞构成；迷走神经是外来神经。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1159","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"心脏的正常起搏点是？","options":["窦房结","房室结","希氏束","浦肯野纤维"],"answer":0,"explanation":"窦房结自律性最高，是正常起搏点。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1160","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"房室结位于？","options":["室间隔膜部","左心房","右心室","房间隔右侧面"],"answer":3,"explanation":"房室结位于房间隔右后部（Koch三角内）。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1161","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"心房与心室在心电图上的除极分别对应？","options":["P波与QRS波","QRS波与P波","T波与P波","P波与T波"],"answer":0,"explanation":"P波为心房除极，QRS为心室除极，T波为心室复极。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1162","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"心包腔穿刺常用的部位是？","options":["左剑肋角（剑突与左肋弓夹角）","心尖区","胸骨右缘第4肋间","腋中线第6肋间"],"answer":0,"explanation":"心包穿刺常选左剑肋角（或心尖部）。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1163","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"主动脉弓的三大分支是？","options":["右颈总、左颈总、左锁骨下","头臂干、左颈总动脉、左锁骨下动脉","头臂干、右锁骨下、左颈总","左颈总、左锁骨下、右颈总"],"answer":1,"explanation":"主动脉弓凸侧从右向左：头臂干、左颈总、左锁骨下。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1164","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"测量血压常听的动脉是？","options":["肱动脉","桡动脉","股动脉","颈总动脉"],"answer":0,"explanation":"测血压听诊肱动脉，触脉常用桡动脉。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1165","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"桡动脉的摸脉位置在？","options":["肘窝","腕尺侧","腕上方桡侧腕屈肌腱外侧","掌心"],"answer":2,"explanation":"桡动脉在腕横纹上方桡侧可触及。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1166","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"颈动脉窦的压力感受器位于？","options":["颈总动脉分叉处膨大","主动脉弓","颈内动脉颅内段","锁骨下动脉"],"answer":0,"explanation":"颈动脉窦是颈总动脉末端和颈内动脉起始部膨大，含压力感受器。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1167","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"颈动脉体（小球）的功能是？","options":["滤过器","压力感受器","化学感受器","内分泌腺"],"answer":2,"explanation":"颈动脉体感受血中O₂、CO₂、H⁺变化，为化学感受器。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1168","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"脑的供血动脉是？","options":["颈外动脉和椎动脉","颈内动脉和椎动脉","颈内动脉和颈外动脉","上颌动脉和椎动脉"],"answer":1,"explanation":"脑由颈内动脉系和椎-基底动脉系供血。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1169","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"大脑动脉环（Willis环）的组成不包括？","options":["前交通动脉","大脑前动脉","大脑中动脉","后交通动脉"],"answer":2,"explanation":"Willis环由大脑前、后动脉起始段、颈内动脉末端、前/后交通动脉构成；不含大脑中动脉。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1170","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"脑膜中动脉来自？","options":["颈内动脉","上颌动脉","椎动脉","面动脉"],"answer":1,"explanation":"脑膜中动脉是上颌动脉的分支，经棘孔入颅。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1171","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"胃的动脉供应不来自？","options":["胃右动脉","胃左动脉","肾动脉","胃网膜右动脉"],"answer":2,"explanation":"胃的血供来自腹腔干的分支（胃左/右、网膜左/右、胃短等）。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1172","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"阑尾动脉来自？","options":["回结肠动脉","回肠动脉","右结肠动脉","肠系膜下动脉"],"answer":0,"explanation":"阑尾动脉是回结肠动脉的分支。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1173","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肠系膜上动脉不供应？","options":["十二指肠以下空回肠","横结肠左1/3","升结肠","横结肠右2/3"],"answer":1,"explanation":"横结肠左1/3由肠系膜下动脉的分支供应。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1174","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肠系膜下动脉的分支不包括？","options":["左结肠动脉","中结肠动脉","乙状结肠动脉","直肠上动脉"],"answer":1,"explanation":"中结肠动脉来自肠系膜上动脉。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1175","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"直肠上动脉来自？","options":["肠系膜上动脉","髂内动脉","阴部内动脉","肠系膜下动脉"],"answer":3,"explanation":"直肠上动脉为肠系膜下动脉的延续。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1176","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"子宫动脉与输尿管的关系是？","options":["平行不相交","动脉在输尿管后方","动脉在输尿管前方交叉","动脉在输尿管下方"],"answer":2,"explanation":"子宫动脉从输尿管前上方跨过（桥下流水），结扎时勿伤输尿管。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1177","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"体循环起于？","options":["右心房","右心室","左心房","左心室"],"answer":3,"explanation":"体循环：左心室→主动脉→全身→右心房。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1178","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肺循环起止是？","options":["左心室起、右心房止","右心室起、左心房止","右心房起、左心室止","左心房起、右心室止"],"answer":1,"explanation":"肺循环：右心室→肺动脉→肺→肺静脉→左心房。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1179","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"卵圆窝位于？","options":["左心房","室间隔","房间隔右侧面","主动脉根部"],"answer":2,"explanation":"卵圆窝是房间隔右心房面的卵圆形凹陷，为胚胎期卵圆孔闭锁遗迹。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1180","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"室间隔缺损最常见的部位是？","options":["膜部","肌部","流出道","流入道"],"answer":0,"explanation":"室间隔膜部薄弱，是先天性室缺最好发部位。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1181","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"动脉导管未闭的解剖基础是？","options":["肺静脉异位引流","房间隔缺损","室间隔缺损","主动脉与肺动脉之间的导管未闭锁"],"answer":3,"explanation":"胎儿期动脉导管连接肺动脉与主动脉，出生后应闭锁为动脉韧带。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1182","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"全身最大的淋巴器官是？","options":["脾","肝","淋巴结","胸腺"],"answer":0,"explanation":"脾是最大的淋巴器官，位于左季肋区。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1183","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"脾的位置在？","options":["腹上区","右季肋区","左季肋区","左腰区"],"answer":2,"explanation":"脾位于左季肋区，第9~11肋深面，长轴与第10肋一致。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1184","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"胸腺的退化时间主要在？","options":["出生时","婴幼儿期","青春期后","老年期"],"answer":2,"explanation":"胸腺在青春期后逐渐退化，被脂肪组织替代。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1185","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"淋巴系统的主要功能不包括？","options":["运输脂肪","回流组织液","免疫防御","分泌消化酶"],"answer":3,"explanation":"淋巴系统回流组织液、运输脂肪、参与免疫；不分泌消化酶。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1186","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"右淋巴导管收集的范围不包括？","options":["右头颈部","左下肢","右上肢","右胸部"],"answer":1,"explanation":"右淋巴导管收集右上肢、右头颈、右胸；左下肢属胸导管。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1187","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"胸导管注入的静脉是？","options":["上腔静脉","右静脉角","左静脉角","奇静脉"],"answer":2,"explanation":"胸导管汇入左静脉角，收集全身约3/4淋巴。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1188","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"乳糜胸的原因是？","options":["胸导管损伤","气管损伤","食管破裂","主动脉破裂"],"answer":0,"explanation":"胸导管损伤致乳糜漏入胸腔，称乳糜胸。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1189","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"心包横窦的临床意义是？","options":["肿瘤好发处","心包积液积聚处","穿刺部位","心脏手术阻断血流的通道"],"answer":3,"explanation":"横窦位于主动脉、肺动脉后方，是术中阻断大血管的通道。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1190","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"冠脉循环的特点是？","options":["舒张期供血为主","收缩期供血为主","与心动周期无关","只供应心房"],"answer":0,"explanation":"冠脉在心舒张期灌注为主，舒张压高低直接影响心肌供血。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1191","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"心肌梗死最常见的原因是？","options":["冠状动脉粥样硬化","心肌炎","瓣膜病","高血压"],"answer":0,"explanation":"冠脉粥样硬化斑块破裂血栓形成是心梗最常见原因。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1192","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"心的静脉大部分经？","options":["下腔静脉","上腔静脉","肺静脉","冠状静脉窦回流入右心房"],"answer":3,"explanation":"心大、中、小静脉汇入冠状窦，开口于右心房。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1193","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"动脉韧带位于？","options":["主动脉弓下缘与肺动脉分叉之间","升主动脉与上腔静脉之间","肺静脉之间","上下腔静脉之间"],"answer":0,"explanation":"动脉韧带是胎儿动脉导管闭锁后的遗迹。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1194","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"体表可触及的动脉搏动不包括？","options":["肋间动脉","桡动脉","肱动脉","股动脉"],"answer":0,"explanation":"肋间动脉位置深不可触及；桡、肱、股、颈、足背等可触及。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1195","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"神经系统的基本结构和功能单位是？","options":["神经元","神经纤维","突触","胶质细胞"],"answer":0,"explanation":"神经元是神经系统的基本结构和功能单位。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1196","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"中枢神经系统包括？","options":["脑和脑神经","脑和脊髓","脊髓和脊神经","脑干和小脑"],"answer":1,"explanation":"中枢=脑+脊髓；周围=脑神经+脊神经+内脏神经。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1197","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"成人的脊髓末端约平？","options":["第1腰椎下缘","第2骶椎","第12胸椎上缘","第3腰椎"],"answer":0,"explanation":"新生儿脊髓止于第3腰椎，成人止于第1腰椎下缘。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1198","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"马尾由什么构成？","options":["终丝","脊髓圆锥","腰骶尾神经根","硬脊膜"],"answer":2,"explanation":"腰骶尾神经根在椎管内下行围绕终丝形成马尾。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1199","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"脊髓的灰质前角含？","options":["交感节前神经元","感觉神经元","运动神经元","副交感神经元"],"answer":2,"explanation":"前角为运动神经元（前角运动细胞），后角为中间/联络神经元。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1200","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"脊髓灰质侧角的交感节前神经元位于？","options":["第2~4骶髓","第1胸髓至第3腰髓","颈髓","第4~5腰髓"],"answer":1,"explanation":"脊髓侧角（T1~L3）含交感节前神经元；S2~4含副交感节前神经元。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1201","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"薄束和楔束的功能是？","options":["传导同侧本体感觉和精细触觉","传导痛温觉","传导对侧本体感觉","传导粗触觉"],"answer":0,"explanation":"薄楔束上行传导同侧意识性本体感觉与精细触觉。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1202","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"脊髓丘脑束传导？","options":["同侧精细触觉","同侧本体感觉","对侧痛温觉和粗触觉","对侧本体感觉"],"answer":2,"explanation":"脊髓丘脑束交叉后上行，传导对侧躯体的痛温觉和粗触觉。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1203","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"脑干包括？","options":["小脑、脑桥、延髓","间脑、中脑、延髓","中脑、脑桥、延髓","中脑、间脑、小脑"],"answer":2,"explanation":"脑干自上而下为中脑、脑桥、延髓。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1204","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"生命中枢位于？","options":["延髓","脑桥","中脑","下丘脑"],"answer":0,"explanation":"延髓内有呼吸、心血管等基本生命中枢。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1205","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"瞳孔对光反射的中枢位于？","options":["中脑","延髓","脑桥","间脑"],"answer":0,"explanation":"瞳孔对光反射中枢在中脑顶盖（上丘/顶盖前区）。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1206","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"角膜反射的传入神经是？","options":["三叉神经","面神经","动眼神经","视神经"],"answer":0,"explanation":"角膜反射：三叉神经传入，面神经传出。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1207","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"小脑的功能不包括？","options":["维持平衡","协调运动","产生意识性感觉","调节肌张力"],"answer":2,"explanation":"小脑协调运动、维持平衡、调节肌张力；不产生意识性感觉。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1208","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"小脑扁桃体疝（枕骨大孔疝）的后果是？","options":["压迫中脑","压迫延髓危及生命","压迫脑桥","压迫间脑"],"answer":1,"explanation":"颅内压增高时小脑扁桃体疝入枕骨大孔，压迫延髓生命中枢。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1209","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"间脑中与内脏活动调节有关的是？","options":["丘脑","下丘脑","上丘脑","后丘脑"],"answer":1,"explanation":"下丘脑是内脏活动（体温、摄食、水平衡、内分泌）的调节中枢。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1210","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"大脑皮层躯体运动区位于？","options":["颞横回","中央后回","中央前回和中央旁小叶前部","距状沟周围"],"answer":2,"explanation":"第Ⅰ躯体运动区在中央前回及中央旁小叶前部；感觉区在中央后回。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1211","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"大脑皮层躯体感觉区位于？","options":["额下回","中央前回","角回","中央后回和中央旁小叶后部"],"answer":3,"explanation":"第Ⅰ躯体感觉区在中央后回及中央旁小叶后部。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1212","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"视觉区位于？","options":["颞横回","距状沟周围皮质","角回","中央后回"],"answer":1,"explanation":"视觉中枢在枕叶距状沟周围；听觉在颞横回。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1213","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"运动性语言中枢（说话中枢）位于？","options":["额中回后部","颞上回后部","角回","额下回后部（Broca区）"],"answer":3,"explanation":"Broca区在额下回后部，损伤致运动性失语（能听懂不能说）。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1214","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"内囊位于？","options":["胼胝体上方","豆状核与屏状核之间","丘脑、尾状核与豆状核之间","侧脑室内"],"answer":2,"explanation":"内囊是丘脑、尾状核与豆状核之间的白质板。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1215","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"内囊出血的典型表现是？","options":["三偏征（偏瘫、偏身感觉障碍、偏盲）","单瘫","截瘫","交叉瘫"],"answer":0,"explanation":"内囊损伤致对侧三偏征。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1216","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"脑脊液的产生部位主要是？","options":["硬脑膜窦","蛛网膜粒","脉络丛","室管膜"],"answer":2,"explanation":"脑脊液主要由各脑室脉络丛产生。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1217","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"脑脊液回收入血的部位是？","options":["室管膜","脉络丛","蛛网膜粒渗入上矢状窦","软脑膜"],"answer":2,"explanation":"脑脊液经蛛网膜粒渗入上矢状窦回流静脉。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1218","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"正常成人脑脊液总量约？","options":["30ml","500ml","150ml（100~160ml）","1000ml"],"answer":2,"explanation":"成人脑脊液总量约150ml，不断产生循环更新。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1219","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"腰椎穿刺抽取脑脊液常选？","options":["第5腰椎与骶椎间","第1、2腰椎间隙","第3、4腰椎间隙","第12胸椎间隙"],"answer":2,"explanation":"成人脊髓止于第1腰椎下缘，L3~4间隙穿刺安全。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1220","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"第1对脑神经是？","options":["滑车神经","视神经","动眼神经","嗅神经"],"answer":3,"explanation":"脑神经顺序：Ⅰ嗅、Ⅱ视、Ⅲ动眼、Ⅳ滑车、Ⅴ三叉……","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1221","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"第Ⅷ对脑神经是？","options":["前庭蜗神经","面神经","舌咽神经","迷走神经"],"answer":0,"explanation":"Ⅷ为前庭蜗（位听）神经。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1222","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"损伤后出现舌肌萎缩和伸舌偏向患侧的是？","options":["舌咽神经","舌下神经","面神经","三叉神经"],"answer":1,"explanation":"舌下神经支配舌肌，损伤后患侧舌肌萎缩、伸舌偏向患侧。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1223","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"面神经的功能不包括？","options":["泪腺和唾液分泌","支配表情肌","舌前2/3味觉","支配咀嚼肌"],"answer":3,"explanation":"咀嚼肌由三叉神经（下颌神经）支配。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1224","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"三叉神经的下颌神经是？","options":["副交感","纯感觉","纯运动","混合性神经"],"answer":3,"explanation":"眼支、上颌支为感觉性，下颌支为混合性。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1225","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"迷走神经的功能不包括？","options":["传导内脏感觉","支配咽喉肌","支配胸腹腔脏器","支配咀嚼肌"],"answer":3,"explanation":"迷走神经支配咽喉肌和胸腹腔脏器（至横结肠左曲附近）；不支配咀嚼肌。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1226","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"交感神经的低级中枢位于？","options":["骶髓","脑干","脊髓第1胸髓至第3腰髓","大脑"],"answer":2,"explanation":"交感低级中枢在T1~L3侧角；副交感在脑干和S2~4。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1227","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"副交感神经的低级中枢位于？","options":["脑干和脊髓第2~4骶节","胸腰段脊髓","交感干","肾上腺髓质"],"answer":0,"explanation":"副交感中枢在脑干（Ⅲ、Ⅶ、Ⅸ、Ⅹ）和S2~4。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1228","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"交感神经兴奋的表现不包括？","options":["支气管扩张","心跳加快","瞳孔缩小","血糖升高"],"answer":2,"explanation":"交感兴奋瞳孔散大；瞳孔缩小是副交感表现。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1229","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"内脏神经的特点是？","options":["不含感觉纤维","完全受意识支配","只含运动纤维","受意识支配不完全"],"answer":3,"explanation":"内脏神经（自主神经）活动不完全受意识控制，含运动和感觉纤维。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1230","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"大脑的动脉供血中，大脑中动脉供血区是？","options":["枕叶后部","大脑半球内侧面","大脑半球背外侧面大部分","小脑"],"answer":2,"explanation":"大脑中动脉供应背外侧面大部（含运动、感觉、语言区），内侧面主要为大脑前动脉。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1231","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"脑疝的类型不包括？","options":["枕骨大孔疝","小脑幕切迹上疝","小脑幕切迹疝","大脑镰下疝"],"answer":1,"explanation":"常见脑疝：小脑幕切迹疝（下疝）、枕骨大孔疝、大脑镰下疝；无切迹上疝。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1232","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"小脑幕切迹疝的典型表现是？","options":["同侧偏瘫","双侧瞳孔缩小","患侧瞳孔散大、对侧偏瘫","失语"],"answer":2,"explanation":"动眼神经受压致患侧瞳孔散大，锥体束受压致对侧偏瘫。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1233","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"脊髓的被膜由外向内是？","options":["软脊膜、蛛网膜、硬脊膜","硬脊膜、蛛网膜、软脊膜","蛛网膜、硬脊膜、软脊膜","硬脊膜、软脊膜、蛛网膜"],"answer":1,"explanation":"脊髓三层被膜由外向内：硬膜、蛛网膜、软膜。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1234","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"硬膜外麻醉的穿刺层次是？","options":["硬脊膜外隙","蛛网膜下隙","软脊膜下","硬膜下隙"],"answer":0,"explanation":"硬膜外麻醉注药于硬脊膜外隙；腰麻注药于蛛网膜下隙。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1235","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"脑和脊髓的被膜之间充满脑脊液的间隙是？","options":["硬膜下隙","硬膜外隙","蛛网膜下隙","软膜下隙"],"answer":2,"explanation":"蛛网膜与软膜之间的蛛网膜下隙充满脑脊液。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1236","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"锥体系的组成是？","options":["上、下两级运动神经元","三级神经元","仅皮质","仅脊髓前角"],"answer":0,"explanation":"锥体系=上运动神经元（皮质）+下运动神经元（脑干/脊髓前角）。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1237","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"上运动神经元瘫痪的特点是？","options":["肌萎缩明显","肌张力降低、腱反射消失","肌张力增高、腱反射亢进、病理征阳性","弛缓性瘫痪"],"answer":2,"explanation":"上运动神经元瘫（中枢性瘫）表现为硬瘫；下运动神经元瘫为软瘫。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1238","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"下运动神经元瘫痪的特点是？","options":["肌张力增高","肌张力降低、腱反射消失、肌萎缩明显","病理征阳性","痉挛性瘫痪"],"answer":1,"explanation":"下运动神经元瘫（周围性瘫）为软瘫，伴肌萎缩和肌束颤动。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1239","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"瞳孔对光反射的传出神经是？","options":["三叉神经","视神经","动眼神经","面神经"],"answer":2,"explanation":"光反射弧：视神经传入→中脑→动眼神经（副交感）传出缩瞳。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1240","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"人体最大的内分泌腺是？","options":["性腺","垂体","肾上腺","甲状腺"],"answer":3,"explanation":"甲状腺是最大的内分泌腺，重约25g。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1241","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"甲状腺分泌的激素是？","options":["甲状旁腺素","甲状腺激素（T3、T4）","降钙素以外的类固醇","肾上腺素"],"answer":1,"explanation":"甲状腺滤泡上皮分泌T3/T4；滤泡旁细胞分泌降钙素。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1242","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"甲状旁腺素的主要作用是？","options":["降低血钙","升高血钙","升高血磷","抑制骨吸收"],"answer":1,"explanation":"PTH促进骨钙释放和肾小管钙重吸收，升高血钙、降低血磷。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1243","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"降钙素的分泌细胞是？","options":["滤泡上皮细胞","甲状腺滤泡旁细胞（C细胞）","甲状旁腺主细胞","肾上腺皮质"],"answer":1,"explanation":"降钙素由甲状腺滤泡旁细胞分泌，降低血钙。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1244","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"垂体分为？","options":["结节部和中间部","前叶和后叶（仅按位置）","漏斗部和远侧部","腺垂体和神经垂体"],"answer":3,"explanation":"垂体分腺垂体（前叶为主）和神经垂体（后叶）。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1245","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"生长激素分泌的腺体是？","options":["神经垂体","腺垂体","甲状腺","肾上腺"],"answer":1,"explanation":"生长激素由腺垂体嗜酸性细胞分泌。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1246","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"神经垂体释放的激素是？","options":["抗利尿激素和催产素","生长激素和催乳素","促甲状腺激素","促肾上腺皮质激素"],"answer":0,"explanation":"ADH（血管加压素）和催产素由下丘脑合成、神经垂体储存释放。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1247","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"抗利尿激素分泌不足导致的疾病是？","options":["尿崩症","巨人症","库欣综合征","甲亢"],"answer":0,"explanation":"ADH缺乏致肾小管重吸收水障碍，出现尿崩症。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1248","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肾上腺皮质由外向内分泌的激素依次是？","options":["盐皮质激素、糖皮质激素、性激素","糖皮质激素、盐皮质激素、性激素","性激素、糖皮质激素、盐皮质激素","盐皮质激素、性激素、糖皮质激素"],"answer":0,"explanation":"球状带→盐皮质激素（醛固酮）；束状带→糖皮质激素；网状带→性激素。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1249","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"糖皮质激素的主要生理作用不包括？","options":["升高血糖","促进蛋白质合成","抗炎","抗过敏"],"answer":1,"explanation":"糖皮质激素促进蛋白质分解（而非合成）、升糖、抗炎抗过敏抗休克。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1250","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肾上腺髓质分泌的激素是？","options":["雄激素","皮质醇","醛固酮","肾上腺素和去甲肾上腺素"],"answer":3,"explanation":"髓质嗜铬细胞分泌儿茶酚胺（肾上腺素、去甲肾上腺素）。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1251","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"胰岛的细胞中分泌胰岛素的是？","options":["PP细胞","A细胞（α细胞）","D细胞","B细胞（β细胞）"],"answer":3,"explanation":"β细胞分泌胰岛素；α细胞分泌胰高血糖素。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1252","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"胰岛素的主要作用是？","options":["抑制葡萄糖利用","升高血糖","促进糖异生","降低血糖"],"answer":3,"explanation":"胰岛素促进组织摄取利用葡萄糖，是唯一降糖激素。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1253","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"胰岛素缺乏导致的疾病是？","options":["甲亢","低血糖症","糖尿病","尿崩症"],"answer":2,"explanation":"1型糖尿病因胰岛素绝对缺乏。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1254","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"松果体分泌的激素是？","options":["催产素","生长激素","褪黑素","甲状腺素"],"answer":2,"explanation":"松果体分泌褪黑素，参与昼夜节律调节。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1255","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"激素作用的特点不包括？","options":["高效能","只作用于固定靶器官","特异性","信使传递"],"answer":1,"explanation":"激素随血液流经全身，作用于有受体的靶细胞，不固定于某一器官。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1256","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"下丘脑与腺垂体的功能联系通过？","options":["垂体柄神经纤维","垂体门脉系统","淋巴管","血液直接混合"],"answer":1,"explanation":"下丘脑促垂体区经垂体门脉系统调节腺垂体。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1257","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"下丘脑与神经垂体的联系通过？","options":["蛛网膜","垂体门脉","下丘脑-垂体束","室管膜"],"answer":2,"explanation":"下丘脑视上核、室旁核经下丘脑-垂体束与神经垂体联系。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1258","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"甲状腺激素的合成原料是？","options":["铁和酪氨酸","碘和色氨酸","碘和酪氨酸","钙和磷"],"answer":2,"explanation":"甲状腺激素以碘和酪氨酸为原料合成。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1259","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"地方性甲状腺肿的主要原因是？","options":["甲状腺炎","甲亢","缺碘","遗传"],"answer":2,"explanation":"缺碘致甲状腺激素合成不足，TSH代偿性增多致甲状腺肿大。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1260","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"呆小症的病因是？","options":["幼年甲状腺激素分泌不足","幼年生长激素不足","成年甲状腺激素不足","成年生长激素过多"],"answer":0,"explanation":"幼年甲状腺激素缺乏致呆小症（智力+体格发育障碍）；生长激素缺乏致侏儒症。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1261","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"侏儒症的病因是？","options":["幼年甲状腺激素不足","幼年生长激素分泌不足","成年生长激素过多","垂体肿瘤"],"answer":1,"explanation":"幼年GH缺乏致身材矮小但智力正常，称垂体性侏儒。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1262","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"巨人症的病因是？","options":["成年生长激素过多","幼年生长激素分泌过多","甲状腺激素过多","胰岛素过多"],"answer":1,"explanation":"幼年GH过多致巨人症；成年GH过多致肢端肥大症。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1263","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肢端肥大症的病因是？","options":["糖皮质激素过多","幼年生长激素过多","成年生长激素分泌过多","醛固酮过多"],"answer":2,"explanation":"成年骨骺已闭合，GH过多致肢端骨增生为肢端肥大症。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1264","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"应激反应时明显升高的激素不包括？","options":["糖皮质激素","胰岛素","肾上腺素","去甲肾上腺素"],"answer":1,"explanation":"应激时儿茶酚胺、糖皮质激素、生长激素等升高；胰岛素分泌受抑制。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1265","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"眼球壁的外层（纤维膜）包括？","options":["虹膜和睫状体","角膜和巩膜","视网膜","脉络膜"],"answer":1,"explanation":"眼球壁外层=角膜+巩膜；中层=虹膜、睫状体、脉络膜；内层=视网膜。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1266","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"眼的屈光系统不包括？","options":["晶状体","角膜","房水","视网膜"],"answer":3,"explanation":"屈光系统=角膜、房水、晶状体、玻璃体；视网膜是感光结构。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1267","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"房水由什么产生？","options":["脉络膜","虹膜","睫状体","巩膜"],"answer":2,"explanation":"房水由睫状体产生，经后房→瞳孔→前房→前房角回流。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1268","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"青光眼的主要原因是？","options":["房水回流受阻、眼压升高","晶状体混浊","视网膜脱离","角膜穿孔"],"answer":0,"explanation":"房水循环受阻致眼压升高，损伤视神经为青光眼。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1269","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"白内障的病变部位是？","options":["玻璃体","角膜","晶状体","视网膜"],"answer":2,"explanation":"晶状体混浊称白内障。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1270","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"视网膜上感光最敏锐的部位是？","options":["视神经盘","黄斑中央凹","视网膜周边","锯状缘"],"answer":1,"explanation":"中央凹只有视锥细胞，感光最敏锐；视神经盘无感光细胞为生理盲点。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1271","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"视神经盘（视乳头）的特点是？","options":["位于黄斑中心","感光最敏锐","只有视杆细胞","无感光细胞，为生理盲点"],"answer":3,"explanation":"视神经盘是视神经穿出处，无视细胞，为生理盲点。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1272","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"视杆细胞的功能是？","options":["感受颜色","感受强光和颜色","感受弱光（暗视觉）","调节晶状体"],"answer":2,"explanation":"视杆细胞感受弱光，无色觉；视锥细胞感受强光和色觉。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1273","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"近视眼的原因是？","options":["角膜变平","眼球前后径过短","晶状体变薄","眼球前后径过长或屈光力过强"],"answer":3,"explanation":"近视眼焦点落在视网膜前，多因眼轴过长。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1274","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"远视眼的原因是？","options":["角膜变凸","眼球前后径过长","晶状体变厚","眼球前后径过短"],"answer":3,"explanation":"远视眼焦点落在视网膜后，多因眼轴过短。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1275","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"老视（老花眼）的原因是？","options":["眼轴变长","晶状体弹性减退","角膜混浊","玻璃体液化"],"answer":1,"explanation":"年龄增长晶状体弹性下降，看近物调节能力减弱。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1276","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"鼓膜的位置是？","options":["外耳道与内耳之间","内耳与中耳的分界","外耳道与中耳的分界","鼻咽部"],"answer":2,"explanation":"鼓膜分隔外耳道与中耳（鼓室）。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1277","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"听觉感受器是？","options":["螺旋器（Corti器）","椭圆囊斑","球囊斑","壶腹嵴"],"answer":0,"explanation":"螺旋器位于蜗管基底膜，是听觉感受器；壶腹嵴感受旋转。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1278","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"平衡觉感受器不包括？","options":["椭圆囊斑","耳蜗","球囊斑","壶腹嵴"],"answer":1,"explanation":"耳蜗司听觉；囊斑感受直线加速，壶腹嵴感受旋转。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1279","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"咽鼓管的功能不包括？","options":["引流分泌物","平衡鼓室内外气压","产生听觉","阻隔自身声音（开放时）"],"answer":2,"explanation":"咽鼓管连通鼓室与鼻咽，平衡气压、引流；不产生听觉。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1280","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"细胞膜的化学组成主要是？","options":["糖类和核酸","脂质和蛋白质","核酸和蛋白质","水和电解质"],"answer":1,"explanation":"细胞膜以脂质（磷脂为主）和蛋白质为基本组成，含少量糖类。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1281","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"细胞膜的物质转运中，O₂和CO₂进入细胞的方式是？","options":["胞吞","易化扩散","主动转运","单纯扩散"],"answer":3,"explanation":"脂溶性小分子（O₂、CO₂、N₂等）经单纯扩散通过细胞膜。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1282","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"葡萄糖进入红细胞的方式是？","options":["易化扩散（载体介导）","单纯扩散","主动转运","胞饮"],"answer":0,"explanation":"葡萄糖经载体蛋白顺浓度梯度易化扩散进入红细胞。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1283","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"Na⁺-K⁺泵的活动属于？","options":["被动转运","主动转运（原发性）","易化扩散","膜泡运输"],"answer":1,"explanation":"Na⁺-K⁺泵直接消耗ATP逆浓度梯度转运，为原发性主动转运。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1284","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"静息电位的产生主要是由于？","options":["K⁺外流","Na⁺内流","Cl⁻内流","Ca²⁺内流"],"answer":0,"explanation":"静息电位主要是K⁺顺浓度梯度经漏通道外流形成的K⁺平衡电位。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1285","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"动作电位的上升支（去极相）主要是由于？","options":["Ca²⁺外流","K⁺外流","Cl⁻外流","Na⁺内流"],"answer":3,"explanation":"动作电位上升支是Na⁺经电压门控通道快速内流所致。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1286","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"动作电位传导的特点是？","options":["可以总和","衰减性传导","不衰减（全或无）","有等级性"],"answer":2,"explanation":"动作电位幅度恒定（全或无），传导不衰减。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1287","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"血细胞中数量最多的是？","options":["血小板","白细胞","红细胞","淋巴细胞"],"answer":2,"explanation":"红细胞正常男性约(4.0~5.5)×10¹²/L，是数量最多的血细胞。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1288","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"正常成人红细胞参考值（男性）是？","options":["(6.0~8.0)×10¹²/L","(3.5~5.0)×10¹²/L","(4.0~5.5)×10¹²/L","(2.0~3.0)×10¹²/L"],"answer":2,"explanation":"男性红细胞4.0~5.5×10¹²/L，女性3.5~5.0×10¹²/L。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1289","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"血红蛋白正常值（成年男性）约为？","options":["170~200g/L","100~120g/L","120~160g/L","80~100g/L"],"answer":2,"explanation":"成年男性Hb约120~160g/L，女性110~150g/L。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1290","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"ABO血型系统中，AB型红细胞上的抗原是？","options":["无抗原","只有A抗原","只有B抗原","A和B抗原"],"answer":3,"explanation":"AB型红细胞含A、B两种抗原，血浆中无抗A抗B抗体。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1291","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"O型血的血浆中含有？","options":["只有抗A抗体","抗A和抗B抗体","只有抗B抗体","无抗体"],"answer":1,"explanation":"O型红细胞无A/B抗原，血浆含抗A、抗B两种抗体。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1292","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"Rh血型系统中，我国汉族人口绝大多数为？","options":["Rh阴性","Rh阳性","各占一半","均为阴性"],"answer":1,"explanation":"汉族Rh阳性约99%以上，阴性不足1%。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1293","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"血浆渗透压的组成不包括？","options":["以晶体渗透压为主","晶体渗透压","胶体渗透压","晶体渗透压以外的胶体渗透压为主要成分"],"answer":3,"explanation":"血浆渗透压以晶体渗透压为主（约99.5%）；胶体渗透压仅约1.5mOsm。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1294","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"维持血管内外水平衡的主要因素是？","options":["血浆胶体渗透压","晶体渗透压","静水压","组织液胶渗压"],"answer":0,"explanation":"血浆胶体渗透压（白蛋白）维持血管内外水平衡；晶体渗透压维持细胞内外。","exam":"医疗编","__sub":"解剖与生理","diff":3,"id":"yl-1295","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"内环境是指？","options":["细胞内液","细胞外液","血浆","组织液"],"answer":1,"explanation":"内环境=细胞外液（血浆、组织液、淋巴液等）。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1296","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"体温的生理波动不包括？","options":["年龄差异","昼夜节律","性别差异","随季节规律性大幅波动"],"answer":3,"explanation":"体温有昼夜（清晨低午后高）、性别、年龄、运动等波动；无季节性大幅波动。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1297","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"体温调节的基本中枢位于？","options":["脊髓","延髓","脑桥","下丘脑"],"answer":3,"explanation":"体温调节基本中枢在下丘脑（PO/AH区）。","exam":"医疗编","__sub":"解剖与生理","diff":1,"id":"yl-1298","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"安静状态下产热最多的器官是？","options":["肾脏","骨骼肌","心脏","肝脏"],"answer":3,"explanation":"安静时肝脏产热最多；运动时骨骼肌为主要产热器官。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1299","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"散热的主要方式是？","options":["只靠蒸发","辐射、传导、对流、蒸发","只靠辐射","只靠传导"],"answer":1,"explanation":"皮肤散热四种方式：辐射（安静时主要）、传导、对流、蒸发（高温时主要）。","exam":"医疗编","__sub":"解剖与生理","diff":2,"id":"yl-1300","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"蛋白质的基本组成单位是？","options":["核苷酸","氨基酸","单糖","脂肪酸"],"answer":1,"explanation":"蛋白质由氨基酸通过肽键连接而成，基本组成单位是氨基酸。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1301","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"组成人体蛋白质的氨基酸大多属于？","options":["L-α-氨基酸","D-α-氨基酸","L-β-氨基酸","D-β-氨基酸"],"answer":0,"explanation":"人体蛋白质由L型α-氨基酸组成（甘氨酸无手性碳除外）。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1302","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"下列属于必需氨基酸的是？","options":["甘氨酸","赖氨酸","丙氨酸","谷氨酸"],"answer":1,"explanation":"必需氨基酸8种：蛋、缬、赖、异亮、苯丙、亮、色、苏；甘、丙、谷为非必需。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1303","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"维持蛋白质一级结构的主要化学键是？","options":["肽键","氢键","盐键","疏水键"],"answer":0,"explanation":"一级结构指氨基酸排列顺序，靠肽键连接（含二硫键）。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1304","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"蛋白质二级结构的主要形式α-螺旋中，每圈含氨基酸残基约？","options":["2.5个","3.6个","4.5个","5.6个"],"answer":1,"explanation":"α-螺旋每圈约3.6个氨基酸残基，螺距0.54nm。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1305","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"维持蛋白质二级结构的主要化学键是？","options":["氢键","肽键","二硫键","酯键"],"answer":0,"explanation":"二级结构（α-螺旋、β-折叠等）主要靠氢键维持。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1306","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"蛋白质变性的本质是？","options":["肽键断裂","空间结构破坏，一级结构不变","氨基酸序列改变","分子量变小"],"answer":1,"explanation":"变性破坏二、三级等空间结构，共价键（肽键）不断裂。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1307","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"蛋白质变性后不会出现的变化是？","options":["分子量减小","生物活性丧失","溶解度降低","易被蛋白酶水解"],"answer":0,"explanation":"变性不破坏肽键，分子量不变；活性丧失、溶解度降低、易水解均可出现。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1308","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"蛋白质在280nm有较强紫外吸收主要是因为含？","options":["甘氨酸","丙氨酸","色氨酸和酪氨酸","脯氨酸"],"answer":2,"explanation":"芳香族氨基酸（色、酪）含共轭双键，在280nm有吸收峰，用于蛋白定量。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1309","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"谷胱甘肽由哪三种氨基酸组成？","options":["谷氨酸、胱氨酸、丙氨酸","谷氨酸、半胱氨酸、甘氨酸","谷氨酰胺、半胱氨酸、甘氨酸","谷氨酸、丝氨酸、甘氨酸"],"answer":1,"explanation":"谷胱甘肽（GSH）由谷、半胱、甘组成，活性基团为半胱氨酸的巯基。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1310","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"蛋白质变性后不易恢复原有性质的原因是？","options":["一级结构被破坏","空间结构破坏难以自发复性","肽键断裂","氨基酸组成改变"],"answer":1,"explanation":"变性使空间结构松散，去除变性因素后复性困难（尤其结构复杂时）。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1311","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"蛋白质变性时断裂的键不包括？","options":["肽键","氢键","疏水键","盐键"],"answer":0,"explanation":"变性破坏次级键（氢键、盐键、疏水作用等），共价肽键不断裂。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1312","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"DNA分子中不含有的碱基是？","options":["胞嘧啶","腺嘌呤","鸟嘌呤","尿嘧啶"],"answer":3,"explanation":"DNA含A、G、C、T；尿嘧啶（U）为RNA特有。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1313","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"DNA双螺旋结构中碱基配对正确的是？","options":["A-U、G-C","A-G、T-C","A-C、G-T","A-T、G-C"],"answer":3,"explanation":"DNA中A与T形成两个氢键，G与C形成三个氢键。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1314","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"核酸中连接相邻核苷酸的化学键是？","options":["糖苷键","肽键","3',5'-磷酸二酯键","氢键"],"answer":2,"explanation":"核苷酸之间以3',5'-磷酸二酯键连接成核酸一级结构。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1315","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"DNA变性的特征性变化是？","options":["分子量减小","280nm吸收增强","一级结构断裂","260nm紫外吸收增强（增色效应）"],"answer":3,"explanation":"DNA变性双链解开，碱基暴露，260nm吸收增强称增色效应。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1316","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"DNA的解链温度（Tm）高低取决于？","options":["A-T含量","G-C含量，G-C越多Tm越高","分子量大小","溶液温度"],"answer":1,"explanation":"G-C间3个氢键，G-C含量越高，双链越稳定，Tm越高。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1317","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"含量最多的RNA是？","options":["rRNA","mRNA","tRNA","snRNA"],"answer":0,"explanation":"rRNA占细胞总RNA的80%以上，是核糖体的组成成分。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1318","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"转运氨基酸的RNA是？","options":["tRNA","mRNA","rRNA","hnRNA"],"answer":0,"explanation":"tRNA携带氨基酸并借反密码子识别mRNA密码子。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1319","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"tRNA的二级结构呈？","options":["三叶草形","双螺旋","超螺旋","发夹单链"],"answer":0,"explanation":"tRNA二级结构为三叶草形，三级结构为例L形。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1320","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"mRNA的功能是？","options":["作为蛋白质合成的模板","转运氨基酸","组成核糖体","储存遗传信息"],"answer":0,"explanation":"mRNA携带密码子信息，指导蛋白质合成；遗传信息储存在DNA。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1321","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"DNA与RNA的分子组成区别不包括？","options":["碱基A、G、C","脱氧核糖与核糖","胸腺嘧啶与尿嘧啶","磷酸"],"answer":3,"explanation":"两者均含磷酸、A、G、C；区别在戊糖和T/U。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1322","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"DNA双螺旋模型中，两条链的走向是？","options":["互相垂直","同向平行","反向平行","随机排列"],"answer":2,"explanation":"DNA两条链反向平行，一条5'→3'，另一条3'→5'。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1323","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"DNA变性时断裂的键是？","options":["糖苷键","磷酸二酯键","碱基对间的氢键","肽键"],"answer":2,"explanation":"变性只破坏维持双链的氢键（二级结构），一级结构不变。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1324","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"酶的化学本质绝大多数是？","options":["脂类","核酸","糖类","蛋白质"],"answer":3,"explanation":"绝大多数酶是蛋白质；少数RNA具有催化活性称核酶。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1325","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"酶与一般催化剂的共同点是？","options":["不改变反应的平衡常数","具有高效性","具有特异性","反应条件温和"],"answer":0,"explanation":"酶与一般催化剂均只加快反应速度，不改变平衡点。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1326","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"酶促反应的特点不包括？","options":["可调节性","高效性","特异性","大幅改变化学平衡点"],"answer":3,"explanation":"酶只加快达到平衡的速度，不改变平衡常数。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1327","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"酶的活性中心是指？","options":["酶与辅酶结合部位","酶分子整个表面","酶分子上与底物结合并催化反应的必需基团聚集区域","酶的变构部位"],"answer":2,"explanation":"活性中心由必需基团组成，结合底物并催化反应。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1328","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"竞争性抑制剂对酶促反应的影响是？","options":["Km、Vmax均降低","Km不变，Vmax降低","Km增大，Vmax不变","Km、Vmax均不变"],"answer":2,"explanation":"竞争性抑制剂与底物竞争活性中心，表观Km增大，Vmax不变。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1329","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"丙二酸对琥珀酸脱氢酶的抑制属于？","options":["非竞争性抑制","竞争性抑制","反竞争性抑制","不可逆抑制"],"answer":1,"explanation":"丙二酸结构与琥珀酸相似，竞争活性中心，为经典竞争性抑制。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1330","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"磺胺类药物抑菌的机制是？","options":["竞争性抑制二氢叶酸合成酶","破坏细菌细胞壁","抑制蛋白质合成","损伤细菌DNA"],"answer":0,"explanation":"磺胺与对氨基苯甲酸结构相似，竞争性抑制二氢叶酸合成酶。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1331","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"酶原激活的实质是？","options":["辅酶脱落","肽键全部断裂","一级结构完全改变","活性中心形成或暴露"],"answer":3,"explanation":"酶原在蛋白酶作用下水解肽段，暴露或形成活性中心而激活。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1332","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"乳酸脱氢酶（LDH）和肌酸激酶（CK）具有多种同工酶，其临床意义是？","options":["不同组织分布不同，可辅助定位诊断","同工酶活性相同","同工酶分子结构完全相同","同工酶只能来自同一器官"],"answer":0,"explanation":"同工酶有组织特异性，如CK-MB升高提示心肌损伤。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1333","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"人体内酶的最适温度大多在？","options":["45~50℃","25~30℃","37~40℃","60℃以上"],"answer":2,"explanation":"体内酶最适温度接近体温37℃左右，温度过高酶蛋白变性失活。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1334","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"属于脂溶性维生素的是？","options":["维生素C","维生素B1","维生素A","维生素B6"],"answer":2,"explanation":"脂溶性维生素为A、D、E、K四种，其余为水溶性。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1335","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"缺乏维生素A可导致？","options":["脚气病","夜盲症","坏血病","佝偻病"],"answer":1,"explanation":"维生素A参与视紫红质合成，缺乏致暗适应下降、夜盲。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1336","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"缺乏维生素D在儿童可引起？","options":["脚气病","夜盲症","佝偻病","坏血病"],"answer":2,"explanation":"维生素D促进钙磷吸收与骨盐沉积，儿童缺乏致佝偻病。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1337","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"缺乏维生素B1可引起？","options":["夜盲症","脚气病","坏血病","恶性贫血"],"answer":1,"explanation":"维生素B1（硫胺素）以TPP形式参与α-酮酸氧化脱羧，缺乏致脚气病。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1338","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"缺乏维生素C可引起？","options":["脚气病","坏血病","佝偻病","夜盲症"],"answer":1,"explanation":"维生素C参与胶原羟化，缺乏致毛细血管脆性增加、坏血病。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1339","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"与凝血因子合成有关的维生素是？","options":["维生素K","维生素A","维生素E","维生素B12"],"answer":0,"explanation":"维生素K参与凝血因子Ⅱ、Ⅶ、Ⅸ、Ⅹ的合成，缺乏易出血。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1340","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"细胞内ATP生成的主要方式是？","options":["氧化磷酸化","底物水平磷酸化","光磷酸化","糖原分解"],"answer":0,"explanation":"线粒体内氧化磷酸化是ATP生成的主要方式。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1341","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"呼吸链（电子传递链）位于？","options":["内质网","线粒体基质","细胞质","线粒体内膜"],"answer":3,"explanation":"NADH和FADH2的氧化呼吸链定位于线粒体内膜。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1342","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"体内CO₂的生成方式是？","options":["呼吸链电子传递","氧气与碳直接化合","碳酸分解","有机酸脱羧"],"answer":3,"explanation":"CO₂由脱羧反应产生，不直接由碳氧结合生成。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1343","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"2,4-二硝基苯酚属于？","options":["解偶联剂","呼吸链抑制剂","ATP合酶激活剂","抗氧化剂"],"answer":0,"explanation":"解偶联剂使氧化与磷酸化解偶联，耗氧产热而不生成ATP。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1344","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"参与呼吸链传电子的细胞色素中，可直接将电子传给氧的是？","options":["Cyt c1","Cyt b","Cyt aa3","Cyt c"],"answer":2,"explanation":"细胞色素氧化酶Cyt aa3（复合体Ⅳ）将电子直接交给O₂。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1345","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"NADH氧化呼吸链每传递2H最终生成ATP约？","options":["4个","1个","2.5个","6个"],"answer":2,"explanation":"NADH呼吸链P/O比约2.5，FADH2呼吸链约1.5。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1346","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"糖酵解的反应部位在？","options":["细胞核","线粒体","内质网","细胞质"],"answer":3,"explanation":"糖酵解全部反应在胞液（细胞质）中进行。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1347","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"糖酵解的终产物是？","options":["丙酮酸","乳酸","乙酰CoA","葡萄糖"],"answer":1,"explanation":"缺氧时丙酮酸由乳酸脱氢酶还原为乳酸。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1348","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"糖酵解的关键酶不包括？","options":["丙酮酸激酶","己糖激酶","磷酸果糖激酶-1","葡萄糖-6-磷酸酶"],"answer":3,"explanation":"糖酵解三个关键酶：己糖激酶、PFK-1、丙酮酸激酶；葡萄糖-6-磷酸酶属糖异生。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1349","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"糖酵解净生成ATP数（1分子葡萄糖）为？","options":["4个","2个","6个","8个"],"answer":1,"explanation":"糖酵解生成4个ATP，消耗2个，净得2个。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1350","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"糖有氧氧化中，丙酮酸氧化脱羧发生在？","options":["高尔基体","细胞质","内质网","线粒体"],"answer":3,"explanation":"丙酮酸进入线粒体，由丙酮酸脱氢酶复合体催化氧化脱羧生成乙酰CoA。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1351","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"丙酮酸脱氢酶复合体不含的辅因子是？","options":["FAD","TPP","硫辛酸","生物素"],"answer":3,"explanation":"该复合体辅因子为TPP、硫辛酸、FAD、NAD⁺、CoA；生物素是羧化酶辅基。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1352","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"三羧酸循环进行的部位是？","options":["溶酶体","细胞质","微粒体","线粒体基质"],"answer":3,"explanation":"三羧酸循环在线粒体基质中进行。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1353","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"三羧酸循环的关键酶不包括？","options":["柠檬酸合酶","苹果酸脱氢酶","异柠檬酸脱氢酶","α-酮戊二酸脱氢酶复合体"],"answer":1,"explanation":"三个关键酶：柠檬酸合酶、异柠檬酸脱氢酶、α-酮戊二酸脱氢酶复合体。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1354","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"1分子乙酰CoA经三羧酸循环可生成？","options":["3分子CO₂","1分子CO₂","2分子CO₂","不产生CO₂"],"answer":2,"explanation":"乙酰CoA进入循环被氧化为2分子CO₂。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1355","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"磷酸戊糖途径的重要生理意义是生成？","options":["FADH₂和核糖","NADH和ATP","NADPH和5-磷酸核糖","NADH和5-磷酸核糖"],"answer":2,"explanation":"该途径产生NADPH（供氢体）和5-磷酸核糖（核苷酸原料）。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1356","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"6-磷酸葡萄糖脱氢酶缺乏症患者溶血的主要诱因是？","options":["进食大量脂肪","进食蚕豆或使用氧化性药物","剧烈运动","感染幽门螺杆菌"],"answer":1,"explanation":"G6PD缺乏（蚕豆病）者红细胞NADPH不足，遇氧化性物质易溶血。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1357","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"糖异生的关键酶不包括？","options":["磷酸烯醇式丙酮酸羧激酶","丙酮酸羧化酶","葡萄糖激酶","果糖二磷酸酶-1"],"answer":2,"explanation":"糖异生四个关键酶：丙酮酸羧化酶、PEP羧激酶、果糖二磷酸酶-1、葡萄糖-6-磷酸酶。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1358","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肌糖原不能直接补充血糖的原因是？","options":["肌组织缺乏葡萄糖-6-磷酸酶","肌糖原不能分解","肌肉不能进行糖酵解","肌糖原结构特殊"],"answer":0,"explanation":"肌糖原分解生成的6-磷酸葡萄糖不能在肌肉中水解脱磷酸。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1359","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"正常成人空腹血糖浓度（静脉血浆）为？","options":["3.9~6.1mmol/L","2.8~3.9mmol/L","6.1~7.8mmol/L","7.8~11.1mmol/L"],"answer":0,"explanation":"空腹血糖3.9~6.1mmol/L；≥7.0mmol/L（空腹）为糖尿病诊断标准之一。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1360","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"脂肪酸β氧化的发生部位是？","options":["细胞核","细胞质","微粒体","线粒体基质"],"answer":3,"explanation":"脂肪酸活化为脂酰CoA后进入线粒体基质进行β氧化。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1361","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"脂肪酸β氧化的四步反应顺序是？","options":["加水、脱氢、硫解、再脱氢","脱氢、加水、再脱氢、硫解","硫解、脱氢、加水、再脱氢","脱氢、硫解、加水、再脱氢"],"answer":1,"explanation":"β氧化每轮经脱氢、加水、再脱氢、硫解，生成1分子乙酰CoA。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1362","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"酮体包括？","options":["丙酮酸、乳酸、乙酰乙酸","乙酰乙酸、β-羟丁酸、丙酮","乙酰CoA、丙酮、乳酸","草酰乙酸、乙酰乙酸、丙酮"],"answer":1,"explanation":"酮体三种成分：乙酰乙酸、β-羟丁酸、丙酮。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1363","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"酮体生成的原料是？","options":["丙酮酸","乙酰CoA","乳酸","甘油"],"answer":1,"explanation":"肝细胞中脂肪酸β氧化产生的乙酰CoA是合成酮体的原料。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1364","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"酮体在肝内生成、肝外利用的原因是？","options":["肝外组织有琥珀酰CoA转硫酶等激活乙酰乙酸的酶","酮体不能出肝","肝内无利用酮体的酶","乙酰CoA不能出线粒体"],"answer":0,"explanation":"肝缺乏激活乙酰乙酸的硫解酶系，肝外组织（心、肾、脑）可氧化酮体。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1365","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"脂肪动员的限速酶是？","options":["脂蛋白脂肪酶","脂肪组织甘油三酯脂肪酶","甘油激酶","乙酰CoA羧化酶"],"answer":1,"explanation":"激素敏感性脂肪酶（脂肪组织TG脂肪酶）是脂肪动员的限速酶。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1366","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"脂肪酸合成的原料乙酰CoA从线粒体进入胞液的途径是？","options":["丙氨酸-葡萄糖循环","柠檬酸-丙酮酸循环","乳酸循环","鸟氨酸循环"],"answer":1,"explanation":"乙酰CoA经柠檬酸-丙酮酸循环转运出线粒体用于脂肪酸合成。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1367","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"脂肪酸合成的限速酶是？","options":["乙酰CoA羧化酶","HMG-CoA还原酶","肉碱脂酰转移酶Ⅰ","脂蛋白脂肪酶"],"answer":0,"explanation":"乙酰CoA羧化酶催化乙酰CoA生成丙二酰CoA，是脂肪酸合成限速酶。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1368","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"胆固醇合成的限速酶是？","options":["乙酰CoA羧化酶","HMG-CoA合酶","HMG-CoA还原酶","鲨烯环氧酶"],"answer":2,"explanation":"HMG-CoA还原酶是胆固醇合成的限速酶，为他汀类药物作用靶点。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1369","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"胆固醇在体内不能转变为？","options":["胆汁酸","脂肪酸","维生素D3","类固醇激素"],"answer":1,"explanation":"胆固醇可转化为胆汁酸、类固醇激素和VitD3，不能转化为脂肪酸。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1370","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"转运内源性甘油三酯的血浆脂蛋白是？","options":["LDL","CM","VLDL","HDL"],"answer":2,"explanation":"CM转运外源性TG，VLDL转运内源性TG，LDL转运胆固醇至肝外。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1371","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"逆向转运胆固醇（从肝外回到肝）的脂蛋白是？","options":["LDL","HDL","VLDL","CM"],"answer":1,"explanation":"HDL将肝外胆固醇运回肝脏代谢，具有抗动脉粥样硬化作用。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1372","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"体内氨基酸脱氨基的主要方式是？","options":["联合脱氨基作用","氧化脱氨基","嘌呤核苷酸循环","脱水脱氨基"],"answer":0,"explanation":"转氨基与谷氨酸氧化脱氨基联合进行，是最主要的脱氨基方式。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1373","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"转氨酶的辅酶是？","options":["四氢叶酸","焦磷酸硫胺素","生物素","磷酸吡哆醛"],"answer":3,"explanation":"磷酸吡哆醛（VitB6的磷酸酯）是转氨酶辅酶。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1374","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"反映肝细胞损伤最常用的血清酶是？","options":["肌酸激酶","淀粉酶","碱性磷酸酶","ALT"],"answer":3,"explanation":"ALT主要存在于肝细胞，肝损伤时释放入血，是肝细胞损伤敏感指标。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1375","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"体内氨的最主要去路是？","options":["合成谷氨酰胺","以铵盐随尿排出","在肝内合成尿素","合成非必需氨基酸"],"answer":2,"explanation":"氨经鸟氨酸循环在肝内合成尿素，是氨的主要去路。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1376","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"尿素合成的部位是？","options":["肌肉","肾脏","肠道","肝细胞的线粒体和胞液"],"answer":3,"explanation":"尿素合成（鸟氨酸循环）在肝细胞线粒体和胞液中进行。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1377","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"鸟氨酸循环中，尿素分子中的两个氮分别来自？","options":["谷氨酸和丙氨酸","两个游离氨","甘氨酸和谷氨酰胺","游离氨和天冬氨酸"],"answer":3,"explanation":"第一个氮来自游离氨，第二个氮来自天冬氨酸。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1378","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"血氨升高引起肝性脑病的机制主要是？","options":["直接溶解脑细胞","抑制呼吸中枢","干扰脑内能量代谢和神经递质","促进脂肪沉积"],"answer":2,"explanation":"氨与α-酮戊二酸结合消耗中间产物，干扰脑细胞三羧酸循环及递质平衡。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1379","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肌肉中氨的运输形式主要是？","options":["天冬酰胺","谷氨酸","丙氨酸（经丙氨酸-葡萄糖循环）","尿素"],"answer":2,"explanation":"肌肉经丙氨酸-葡萄糖循环以丙氨酸形式向肝运氨。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1380","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"脑内氨的主要运输（解毒）形式是？","options":["铵盐","尿素","丙氨酸","谷氨酰胺"],"answer":3,"explanation":"脑内氨与谷氨酸结合生成谷氨酰胺，经血液运至肝、肾。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1381","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"一碳单位的载体是？","options":["四氢叶酸","S-腺苷蛋氨酸","生物素","磷酸吡哆醛"],"answer":0,"explanation":"一碳单位（甲基、亚甲基等）由四氢叶酸携带转运。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1382","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"嘌呤核苷酸分解代谢的终产物是？","options":["肌酐","尿素","尿酸","β-丙氨酸"],"answer":2,"explanation":"嘌呤碱最终氧化为尿酸；嘧啶分解产生β-丙氨酸等。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1383","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"痛风症患者血中升高的物质是？","options":["胆红素","尿素氮","肌酐","尿酸"],"answer":3,"explanation":"嘌呤代谢障碍使尿酸生成过多或排泄减少，尿酸盐沉积致痛风。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1384","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"别嘌醇治疗痛风的机制是？","options":["补充嘌呤","促进尿酸排泄","抑制尿酸重吸收","抑制黄嘌呤氧化酶"],"answer":3,"explanation":"别嘌醇结构与次黄嘌呤相似，抑制黄嘌呤氧化酶减少尿酸生成。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1385","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"嘧啶核苷酸分解代谢的产物不包括？","options":["CO₂","NH₃","尿酸","β-丙氨酸"],"answer":2,"explanation":"嘧啶分解产生NH₃、CO₂和β-丙氨酸（或β-氨基异丁酸）；尿酸属嘌呤代谢。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1386","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"甲氨蝶呤抗肿瘤作用的机制是？","options":["抑制胸苷酸合酶","抑制二氢叶酸还原酶","抑制DNA聚合酶","破坏DNA结构"],"answer":1,"explanation":"MTX抑制二氢叶酸还原酶，阻断四氢叶酸生成，干扰核苷酸合成。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1387","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"饥饿时脑的主要能源物质变化是？","options":["始终只用葡萄糖","长期饥饿时以酮体供能为主","以脂肪酸直接供能","以氨基酸供能为主"],"answer":1,"explanation":"脑不能直接利用脂肪酸，长期饥饿时以酮体为主要能源。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1388","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"成熟红细胞的供能方式是？","options":["脂肪酸氧化","有氧氧化","磷酸戊糖途径供能为主","糖酵解"],"answer":3,"explanation":"成熟红细胞无线粒体，只能靠糖酵解供能。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1389","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"红细胞内的2,3-二磷酸甘油酸（2,3-BPG）的作用是？","options":["促进氧的运输载体生成","促进糖酵解供能","稳定红细胞膜","降低血红蛋白对氧的亲和力"],"answer":3,"explanation":"2,3-BPG与Hb结合使其氧解离曲线右移，利于氧释放。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1390","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"关于物质代谢的特点，错误的是？","options":["全身代谢整体协调","代谢途径受调节","能量物质可互相转变","各代谢途径彼此孤立、互不联系"],"answer":3,"explanation":"各代谢途径通过共同中间产物（如乙酰CoA）相互联系、整体调节。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1391","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"短期饥饿时血糖的主要来源是？","options":["脂肪直接转变为葡萄糖","肌糖原分解直接入血","肝糖原分解和糖异生","食物糖吸收"],"answer":2,"explanation":"短期饥饿靠肝糖原分解维持血糖，随后糖异生逐渐成为主要来源。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1392","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"DNA复制的特点是？","options":["全不连续复制","全保留复制、连续复制","随机复制","半保留复制、半不连续复制"],"answer":3,"explanation":"复制时亲代双链各保留一条（半保留），后随链不连续合成（半不连续）。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1393","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"证明DNA半保留复制的经典实验是？","options":["Griffith转化实验","Meselson-Stahl实验","Hershey-Chase实验","Watson-Crick模型构建"],"answer":1,"explanation":"Meselson-Stahl用¹⁵N标记密度梯度离心证明半保留复制。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1394","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"DNA聚合酶催化核苷酸聚合的方向是？","options":["随机方向","3'→5'","双向","5'→3'"],"answer":3,"explanation":"所有DNA聚合酶只能沿5'→3'方向延伸新链。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1395","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"DNA复制中引物的化学本质是？","options":["多肽","DNA","蛋白质","RNA"],"answer":3,"explanation":"引物酶以DNA为模板合成短链RNA引物，提供3'-OH起始DNA合成。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1396","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"连接冈崎片段的酶是？","options":["DNA连接酶","DNA聚合酶Ⅲ","解旋酶","引物酶"],"answer":0,"explanation":"后随链上的冈崎片段由DNA连接酶连接成完整链。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1397","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"紫外线对DNA的典型损伤是？","options":["形成嘧啶二聚体","碱基脱落","单链断裂","碱基替换"],"answer":0,"explanation":"紫外线使相邻嘧啶碱基交联形成二聚体，影响复制转录。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1398","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"端粒酶的化学本质属于？","options":["DNA聚合酶","自带RNA模板的反转录酶","RNA聚合酶","核酸外切酶"],"answer":1,"explanation":"端粒酶以自身RNA为模板反转录延长端粒，属反转录酶。","exam":"医疗编","__sub":"病理与药理","diff":3,"id":"yl-1399","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"DNA复制中解开双链的酶是？","options":["连接酶","解旋酶","拓扑异构酶","限制性内切酶"],"answer":1,"explanation":"解旋酶破坏氢键解开双链；拓扑异构酶松解超螺旋。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1400","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"细胞、组织或器官体积缩小称为？","options":["化生","肥大","增生","萎缩"],"answer":3,"explanation":"萎缩指发育正常的细胞、组织或器官体积缩小，常伴细胞数量减少。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1401","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"高血压病患者左心室壁增厚属于？","options":["肥大","萎缩","化生","变性"],"answer":0,"explanation":"长期压力负荷使心肌细胞体积增大，为代偿性肥大。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1402","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"一种分化成熟的细胞被另一种分化成熟的细胞取代称为？","options":["再生","增生","化生","肥大"],"answer":2,"explanation":"化生是适应反应，如慢性支气管炎的鳞状上皮化生。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1403","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"慢性支气管炎假复层纤毛柱状上皮转变为鳞状上皮属于？","options":["再生","肠上皮化生","增生","鳞状上皮化生"],"answer":3,"explanation":"柱状上皮在慢性刺激下化生为鳞状上皮。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1404","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"慢性萎缩性胃炎胃黏膜上皮转变为含有杯状细胞的肠上皮属于？","options":["肿瘤性增生","鳞状上皮化生","异位增生","肠上皮化生"],"answer":3,"explanation":"胃黏膜上皮化生为肠上皮称肠化生，与胃癌发生有关。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1405","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"细胞水肿（水样变性）的主要发生机制是？","options":["溶酶体增多","细胞器数量增多","线粒体受损、ATP生成减少致细胞内水钠潴留","细胞膜通道增多"],"answer":2,"explanation":"缺氧等损伤线粒体，能量不足，细胞膜钠泵障碍致水肿。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1406","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"细胞脂肪变最常发生的器官是？","options":["心","肝","肾","脾"],"answer":1,"explanation":"肝是脂肪代谢主要场所，脂肪变最常见于肝。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1407","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"心肌脂肪变时形成黄褐色条纹，称为？","options":["梨形心","绒毛心","靴形心","虎斑心"],"answer":3,"explanation":"心肌脂肪变与正常心肌相间呈黄红条纹，似虎斑，称虎斑心。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1408","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"细胞内或间质中出现半透明、均质红染物质称为？","options":["黏液样变性","脂肪变性","玻璃样变性","淀粉样变性"],"answer":2,"explanation":"玻璃样变（透明变性）为均质红染的蛋白样物质沉积。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1409","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"细胞坏死的主要形态学标志是？","options":["线粒体增多","细胞体积增大","核固缩、核碎裂、核溶解","细胞膜完整"],"answer":2,"explanation":"坏死时细胞核出现固缩、碎裂、溶解等不可逆改变。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1410","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"坏死组织水分减少、蛋白质凝固呈灰白干燥外观，属于？","options":["凝固性坏死","液化性坏死","脂肪坏死","坏疽"],"answer":0,"explanation":"凝固性坏死常见于心、肾、脾等实质器官缺血性坏死。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1411","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"脑组织坏死属于？","options":["凝固性坏死","液化性坏死","干性坏疽","纤维素样坏死"],"answer":1,"explanation":"脑组织含磷脂多、蛋白少，坏死后液化呈羹状，为液化性坏死。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1412","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"结核病引起的坏死属于？","options":["脂肪坏死","液化性坏死","干酪样坏死","坏疽"],"answer":2,"explanation":"结核结节中心干酪样坏死，为特殊类型的凝固性坏死。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1413","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"糖尿病足部干性坏疽的发生条件是？","options":["动静脉同时阻塞","静脉阻塞而动脉通畅","动脉阻塞而静脉通畅","仅淋巴回流障碍"],"answer":2,"explanation":"动脉供血断绝、静脉回流通畅，坏死组织水分蒸发呈干黑状。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1414","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"湿性坏疽多发生的部位是？","options":["脾","四肢末端","肠、肺、子宫等与外界相通的内脏","肾"],"answer":2,"explanation":"湿性坏疽多见于肠、肺、阑尾等，腐败菌感染重、组织肿胀。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1415","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"风湿病病变中结缔组织出现的坏死属于？","options":["液化性坏死","干酪样坏死","纤维素样坏死","脂肪坏死"],"answer":2,"explanation":"纤维素样坏死见于风湿病、恶性高血压血管壁等。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1416","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"细胞凋亡的特点是？","options":["程序性细胞死亡，不引起炎症反应","细胞膜破裂、内容物外溢","引起明显炎症","被动性损伤死亡"],"answer":0,"explanation":"凋亡是基因调控的程序性死亡，形成凋亡小体，无炎症。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1417","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"坏死与凋亡的主要区别是？","options":["坏死有细胞膜改变","凋亡是主动程序性死亡且不伴炎症","凋亡由损伤引起","坏死不伴炎症"],"answer":1,"explanation":"凋亡为主动、单个细胞、无炎症；坏死为被动、成片、伴炎症。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1418","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"坏死组织与正常组织分界清楚、颜色苍白干燥，见于？","options":["湿性坏疽","干性坏疽","气性坏疽","液化性坏死"],"answer":1,"explanation":"干性坏疽坏死组织干燥、边界清楚，多见于四肢。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1419","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"气性坏疽的病原体主要是？","options":["结核分枝杆菌","金黄色葡萄球菌","产气荚膜梭菌","大肠埃希菌"],"answer":2,"explanation":"深部开放性创伤合并产气荚膜梭菌感染，组织含气泡。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1420","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"坏死的结局不包括？","options":["分离排出","溶解吸收","细胞再生为原有细胞并完全恢复功能（坏死组织原位）","机化包裹"],"answer":2,"explanation":"坏死组织不能原地复活，经溶解吸收、排出、机化、包裹钙化等处理。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1421","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"坏死组织被肉芽组织取代的过程称为？","options":["钙化","化生","机化","再生"],"answer":2,"explanation":"肉芽组织长入并取代坏死组织称机化。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1422","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"坏死组织内出现钙盐沉积称为？","options":["机化","转移性钙化","骨化","营养不良性钙化"],"answer":3,"explanation":"坏死组织钙化为营养不良性钙化，血钙正常。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1423","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"细胞缺氧时最先发生改变的细胞器是？","options":["线粒体","细胞核","溶酶体","高尔基体"],"answer":0,"explanation":"线粒体是氧化供能场所，缺氧时最早肿胀、产能下降。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1424","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"细胞可逆性损伤中最常见的是？","options":["细胞水肿","脂肪变","玻璃样变","黏液样变"],"answer":0,"explanation":"细胞水肿（水样变性）是缺氧等损伤最早、最常见的可逆改变。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1425","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肉芽组织的组成是？","options":["上皮细胞和腺体","神经纤维和血管","平滑肌和胶原","新生毛细血管、成纤维细胞和炎细胞"],"answer":3,"explanation":"肉芽组织由新生的毛细血管、成纤维细胞及炎细胞构成。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1426","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肉芽组织中对抗感染的主要成分是？","options":["成纤维细胞","炎细胞","毛细血管","胶原纤维"],"answer":1,"explanation":"肉芽组织中的中性粒细胞和巨噬细胞发挥抗感染作用。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1427","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肉芽组织成熟后转变为？","options":["软骨组织","脂肪组织","肌肉组织","瘢痕组织"],"answer":3,"explanation":"肉芽组织胶原沉积、血管减少，最终变为瘢痕。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1428","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"健康肉芽组织的肉眼特点是？","options":["黄白色、质硬","苍白、凹陷","灰黑、干燥","鲜红、颗粒状、湿润、触之易出血"],"answer":3,"explanation":"健康肉芽鲜红颗粒状，分泌物少，触之出血。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1429","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"创伤一期愈合的条件是？","options":["创缘不整齐","组织缺损大","组织缺损少、创缘整齐、无感染","有明显感染"],"answer":2,"explanation":"一期愈合见于整齐清洁小伤口，瘢痕小。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1430","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"二期愈合与一期愈合的主要区别是？","options":["瘢痕更小","愈合速度更快","组织缺损大、创缘不整齐、伴感染，愈合时间长、瘢痕大","不形成肉芽组织"],"answer":2,"explanation":"二期愈合缺损大、需更多肉芽组织填充，瘢痕大。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1431","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"骨折愈合的正确过程是？","options":["骨性骨痂→血肿→改建","血肿形成→纤维性骨痂→骨性骨痂→骨痂改建","纤维性骨痂→血肿→骨痂改建","改建→骨痂→血肿"],"answer":1,"explanation":"骨折愈合经历血肿、纤维性骨痂、骨性骨痂及改建四期。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1432","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"影响创伤愈合的全身因素不包括？","options":["蛋白质缺乏","局部异物存留","维生素C缺乏","年龄"],"answer":1,"explanation":"局部异物属局部因素；营养、年龄、激素等为全身因素。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1433","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"瘢痕组织对机体的有利作用是？","options":["填补伤口、保持组织完整性","引起瘢痕收缩","导致器官粘连","形成瘢痕疙瘩"],"answer":0,"explanation":"瘢痕填补缺损、连接牢固，是其有利方面。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1434","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"瘢痕收缩可引起的并发症不包括？","options":["器官粘连","关节挛缩","管腔狭窄","促进伤口愈合加速上皮再生"],"answer":3,"explanation":"瘢痕收缩牵拉可致畸形、狭窄、粘连，不会加速上皮再生。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1435","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"稳定细胞（肝细胞、肾小管上皮等）的再生能力特点是？","options":["正常时无增殖，受损伤后可较强再生","永远不能再生","持续快速增殖","只能肥大不能增生"],"answer":0,"explanation":"稳定细胞在生理静止、受刺激后进入增殖，如肝细胞。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1436","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"属于永久性细胞（不能再生）的是？","options":["皮肤表皮","肝细胞","神经细胞（神经元）","成纤维细胞"],"answer":2,"explanation":"神经细胞、心肌细胞、骨骼肌细胞属永久细胞，坏死后由瘢痕修复。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1437","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"静脉性充血又称？","options":["动脉性充血","淤血","缺血","水肿"],"answer":1,"explanation":"静脉回流受阻致血液淤积称静脉性充血（淤血）。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1438","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"左心衰竭时淤血的器官主要是？","options":["肺","肝","脾","肾"],"answer":0,"explanation":"左心衰致肺淤血，右心衰致体循环淤血（肝、脾等）。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1439","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"慢性肺淤血时肺泡内出现的特征性细胞是？","options":["泡沫细胞","心衰细胞（含含铁血黄素的巨噬细胞）","朗汉斯巨细胞","R-S细胞"],"answer":1,"explanation":"肺淤血时红细胞被巨噬细胞吞噬形成含铁血黄素，称心衰细胞。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1440","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"慢性肝淤血的病理特征是？","options":["肝小叶中央静脉周围肝窦扩张、肝细胞脂肪变","汇管区大量中性粒细胞浸润","肝细胞大片坏死","假小叶形成"],"answer":0,"explanation":"肝淤血时小叶中央静脉周围淤血，肝细胞萎缩脂肪变，切面呈槟榔状。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1441","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"血栓形成的条件不包括？","options":["血液凝固性增高","心血管内膜损伤","血流缓慢","血管壁光滑完整"],"answer":3,"explanation":"内膜损伤、血流缓慢或涡流、血液高凝是血栓形成三条件；内膜光滑不易形成血栓。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1442","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"静脉血栓的头部主要由什么构成？","options":["混合血栓","红色血栓","白色血栓（血小板和纤维蛋白）","透明血栓"],"answer":2,"explanation":"血栓头为白色血栓，体部混合血栓，尾部红色血栓。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1443","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"延续性血栓的体部是？","options":["透明血栓","白色血栓","红色血栓","混合血栓"],"answer":3,"explanation":"静脉延续性血栓：头部白色、体部混合、尾部红色。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1444","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"弥漫性血管内凝血（DIC）微循环内形成的血栓是？","options":["透明血栓（纤维蛋白性）","白色血栓","红色血栓","混合血栓"],"answer":0,"explanation":"DIC时微血管内纤维蛋白性血栓，镜下均质红染，称透明血栓。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1445","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"血栓的结局不包括？","options":["机化","溶解吸收","再通后恢复原有正常血管结构","钙化"],"answer":2,"explanation":"再通是机化后血流部分恢复，血管不能恢复原有正常结构。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1446","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"循环血液中的异常物质随血流阻塞血管腔称为？","options":["充血","梗死","血栓形成","栓塞"],"answer":3,"explanation":"血栓形成指活体内血液凝固；栓子运行阻塞血管为栓塞。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1447","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"来自左心的血栓栓子最常栓塞的部位是？","options":["脑、肾、脾、下肢动脉","肺动脉","门静脉","肺静脉"],"answer":0,"explanation":"左心栓子随体循环栓塞脑、肾、脾等动脉。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1448","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"长期卧床患者下静脉血栓脱落最常引起？","options":["脑栓塞","肺动脉栓塞","肾梗死","肠梗死"],"answer":1,"explanation":"下肢静脉血栓经右心入肺，引起肺动脉栓塞。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1449","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"减压病（沉箱病）的栓塞类型是？","options":["氮气栓塞","血栓栓塞","羊水栓塞","脂肪栓塞"],"answer":0,"explanation":"从高压环境快速进入低压环境，氮气析出形成气泡栓塞。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1450","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"长骨骨折患者突然出现呼吸困难、意识障碍，最可能的栓塞是？","options":["空气栓塞","血栓栓塞","羊水栓塞","脂肪栓塞"],"answer":3,"explanation":"骨折后脂肪滴入血，栓塞肺小动脉和脑微血管。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1451","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"梗死灶呈地图状（楔形、尖端朝向门部）的器官是？","options":["脑","肠","脾、肾、肺","心脏"],"answer":2,"explanation":"脾肾梗死灶呈锥形/楔形，尖端指向血管阻塞处（门部）。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1452","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"贫血性梗死多发生于？","options":["肺（伴淤血时）","肠","心、肾、脾等实质器官，组织致密侧支循环少","子宫"],"answer":2,"explanation":"组织致密、侧支少的实质器官易发生贫血性（白色）梗死。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1453","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"出血性梗死常发生的器官是？","options":["脑","肾和脾","肺和肠","心肌"],"answer":2,"explanation":"肺（双重血供伴淤血）和肠（疏松组织）易发生出血性梗死。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1454","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"脑梗死多属于？","options":["出血性梗死","贫血性梗死（液化性坏死）","干性坏疽","湿性坏疽"],"answer":1,"explanation":"脑梗死常为贫血性梗死，坏死后液化。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1455","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"炎症的基本病理变化是？","options":["充血、水肿、坏死","变质、渗出、增生","变性、坏死、再生","化生、增生、机化"],"answer":1,"explanation":"炎症基本病变为变质（变性坏死）、渗出、增生。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1456","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"炎症最重要的特征是？","options":["坏死","变质","增生","渗出"],"answer":3,"explanation":"血管反应和渗出是炎症最具特征性的变化。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1457","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"炎症局部表现不包括？","options":["肿","红","功能障碍减轻","热"],"answer":2,"explanation":"炎症局部表现为红、肿、热、痛和功能障碍。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1458","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"炎症时渗出的主要液体来自？","options":["细胞内液","组织细胞","淋巴管","血管内血浆成分"],"answer":3,"explanation":"炎症介质使血管通透性增高，血浆成分渗出。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1459","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"化脓性炎组织中浸润的主要细胞是？","options":["淋巴细胞","嗜酸性粒细胞","中性粒细胞","浆细胞"],"answer":2,"explanation":"化脓性炎以中性粒细胞渗出为主，伴组织液化。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1460","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"寄生虫感染和过敏反应时浸润的炎细胞主要是？","options":["中性粒细胞","嗜酸性粒细胞","单核细胞","红细胞"],"answer":1,"explanation":"嗜酸性粒细胞常见于寄生虫感染和Ⅰ型超敏反应。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1461","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"病毒感染和慢性炎症时浸润的主要细胞是？","options":["嗜碱性粒细胞","中性粒细胞","淋巴细胞","血小板"],"answer":2,"explanation":"病毒感染及慢性炎症以淋巴细胞、单核细胞浸润为主。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1462","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"脓肿壁的形成主要依靠？","options":["纤维蛋白","坏死组织","肉芽组织","上皮细胞"],"answer":2,"explanation":"脓肿周围由肉芽组织包绕形成脓肿壁。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1463","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"蜂窝织炎常见于？","options":["浆膜面","实质器官内","皮下、肌间等疏松结缔组织","骨组织"],"answer":2,"explanation":"溶血性链球菌分泌透明质酸酶等，疏松组织内弥漫性化脓。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1464","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"浆液性炎的好发部位不包括？","options":["浆膜","皮肤（水疱）","骨髓","黏膜"],"answer":2,"explanation":"浆液性炎见于皮肤水疱、浆膜腔积液、黏膜卡他性炎；骨髓不发生。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1465","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"白喉和菌痢的病变属于？","options":["纤维素性炎","浆液性炎","化脓性炎","出血性炎"],"answer":0,"explanation":"黏膜纤维素性炎形成假膜（白喉、菌痢）。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1466","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"绒毛心的病变基础是？","options":["心瓣膜赘生物","心包化脓性炎","心包纤维素性炎","心肌坏死"],"answer":2,"explanation":"纤维素性心包炎时心包表面绒毛状纤维素，称绒毛心。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1467","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"炎症介质组胺的主要作用是？","options":["趋化中性粒细胞","扩张小血管、增加血管通透性","直接破坏细菌","引起组织坏死"],"answer":1,"explanation":"组胺由肥大细胞释放，扩张血管、升高通透性。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1468","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"炎症的吞噬细胞主要包括？","options":["红细胞和血小板","淋巴细胞和浆细胞","嗜酸和嗜碱粒细胞","中性粒细胞和巨噬细胞"],"answer":3,"explanation":"中性粒细胞和巨噬细胞是主要吞噬细胞。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1469","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"巨噬细胞吞噬结核杆菌后形成的细胞是？","options":["上皮样细胞","泡沫细胞","心衰细胞","尘细胞"],"answer":0,"explanation":"结核感染时巨噬细胞转变为上皮样细胞，可融合成朗汉斯巨细胞。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1470","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肉芽肿性炎的特征性细胞是？","options":["浆细胞","中性粒细胞","嗜酸性粒细胞","上皮样细胞和多核巨细胞"],"answer":3,"explanation":"肉芽肿由巨噬细胞及其衍生细胞（上皮样细胞、多核巨细胞）构成。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1471","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"属于肉芽肿性炎的疾病是？","options":["结核病","大叶性肺炎","蜂窝织炎","急性阑尾炎"],"answer":0,"explanation":"结核、伤寒、风湿病、梅毒等属肉芽肿性炎。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1472","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"伤寒小结的主要细胞是？","options":["浆细胞","上皮样细胞","中性粒细胞","伤寒细胞（吞噬淋巴细胞红细胞的巨噬细胞）"],"answer":3,"explanation":"伤寒肉芽肿由伤寒细胞（吞噬红细胞等）组成。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1473","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"炎症的结局不包括？","options":["迁延为慢性","痊愈","病原体在体内无限繁殖扩散（必然）","蔓延扩散"],"answer":2,"explanation":"炎症可痊愈、迁延慢性或蔓延扩散，但不是必然无限扩散。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1474","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"菌痢假膜脱落后形成的溃疡特点是？","options":["大小不等、形状不一的浅溃疡","烧瓶状溃疡","环形溃疡","纵行裂隙状溃疡"],"answer":0,"explanation":"菌痢为浅表不规则溃疡；阿米巴为烧瓶状；肠结核为环形。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1475","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"炎症时白细胞从血管内游出到达组织的定向运动称为？","options":["吞噬作用","趋化作用","黏附作用","渗出作用"],"answer":1,"explanation":"炎细胞沿化学梯度定向移动称趋化。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1476","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"急性炎症早期（24小时内）最先浸润的细胞是？","options":["淋巴细胞","中性粒细胞","巨噬细胞","浆细胞"],"answer":1,"explanation":"急性炎症早期以中性粒细胞为主，48小时后单核细胞增多。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1477","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肿瘤的实质是指？","options":["肿瘤细胞","肿瘤内血管","结缔组织","炎细胞"],"answer":0,"explanation":"实质即肿瘤细胞，决定肿瘤性质；间质为血管结缔组织。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1478","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肿瘤的异型性是指？","options":["肿瘤大小差异","肿瘤组织在细胞和组织结构上与正常组织的差异","肿瘤生长速度差异","肿瘤部位差异"],"answer":1,"explanation":"异型性是诊断肿瘤、区分良恶性的重要依据。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1479","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"判断肿瘤良恶性的主要依据是？","options":["肿瘤大小","异型性大小","生长时间","患者年龄"],"answer":1,"explanation":"分化程度高（异型性小）者良性，异型性大者恶性。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1480","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"恶性肿瘤细胞最重要的形态学特征是？","options":["病理性核分裂象","细胞体积增大","胞质丰富","细胞膜清晰"],"answer":0,"explanation":"病理性核分裂象（不对称、多极等）是恶性肿瘤的重要标志。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1481","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肿瘤的生长方式不包括？","options":["膨胀性生长","浸润性生长的良性生长","外生性生长","浸润性生长"],"answer":1,"explanation":"良性肿瘤多膨胀性或外生性生长；浸润性生长为恶性特征。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1482","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"恶性肿瘤最主要的生长方式是？","options":["膨胀性生长","浸润性生长","外生性生长","停滞生长"],"answer":1,"explanation":"恶性肿瘤沿组织间隙、血管淋巴管浸润蔓延。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1483","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"癌与肉瘤的根本区别是？","options":["组织来源（上皮组织与间叶组织）","生长速度","转移途径","发病年龄"],"answer":0,"explanation":"癌来自上皮组织，肉瘤来自间叶组织。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1484","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"癌最常见的转移方式是？","options":["直接蔓延","血道转移","种植性转移","淋巴道转移"],"answer":3,"explanation":"癌多经淋巴道转移；肉瘤多经血道转移。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1485","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"胃癌晚期癌细胞脱落到卵巢形成转移瘤，属于？","options":["淋巴道转移","种植性转移","血道转移","直接蔓延"],"answer":1,"explanation":"体腔内脱落的癌细胞种植于浆膜或器官表面。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1486","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"血道转移最常见的靶器官是？","options":["脑和骨","脾和肾","肺和肝","皮肤"],"answer":2,"explanation":"肺是体循环静脉血必经之地，肝是门静脉血必经之地。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1487","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"原位癌是指？","options":["癌组织广泛坏死","癌细胞侵入肌层","癌发生淋巴转移","癌细胞局限于上皮层内未突破基底膜"],"answer":3,"explanation":"原位癌未突破基底膜，无浸润转移，早期能治愈。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1488","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"原位癌进一步发展，癌细胞突破基底膜称为？","options":["原位癌复发","浸润癌（早期浸润癌）","癌前病变","良性肿瘤"],"answer":1,"explanation":"突破基底膜进入间质即为浸润。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1489","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"属于癌前病变的是？","options":["原位癌","黏膜白斑","浸润癌","良性肿瘤"],"answer":1,"explanation":"常见癌前病变：黏膜白斑、结肠腺瘤性息肉、乳腺纤维囊性病、慢性萎缩性胃炎伴肠化等。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1490","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"非典型增生（异型增生）是指？","options":["已经癌变","增生的细胞出现异型性但未达癌的程度","炎症细胞增生","间质增生"],"answer":1,"explanation":"异型增生细胞形态异常，属癌前状态，可逆转或进展。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1491","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肿瘤异型性最小的是？","options":["中分化肿瘤","低分化肿瘤","未分化肿瘤","高分化肿瘤"],"answer":3,"explanation":"分化越高，越接近正常组织，异型性越小。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1492","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"未分化肿瘤的特点是？","options":["不转移","分化良好","生长缓慢","恶性程度高，难以判断组织来源"],"answer":3,"explanation":"未分化癌异型性极大，恶性程度最高。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1493","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"诊断霍奇金淋巴瘤的特征性细胞是？","options":["朗汉斯巨细胞","泡沫细胞","心衰细胞","R-S细胞（Reed-Sternberg细胞）"],"answer":3,"explanation":"R-S细胞（镜影细胞）是霍奇金淋巴瘤的诊断依据。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1494","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"肿瘤的间质主要由什么构成？","options":["肌肉组织","肿瘤细胞","神经组织","结缔组织和血管"],"answer":3,"explanation":"间质起支持和营养作用，由纤维组织和血管构成。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1495","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"良性肿瘤对机体的影响主要取决于？","options":["肿瘤大小","发生部位和继发改变","肿瘤颜色","患者性别"],"answer":1,"explanation":"颅内、椎管内等关键部位良性肿瘤也可致命。","exam":"医疗编","__sub":"病理与药理","diff":2,"id":"yl-1496","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"恶性肿瘤晚期患者死亡的主要原因不包括？","options":["恶病质","良性肿瘤恶变","重要器官转移破坏","大出血"],"answer":1,"explanation":"恶病质、器官功能衰竭、出血感染是主要死因。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1497","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"与EB病毒相关的肿瘤是？","options":["结肠癌","胃癌","鼻咽癌","皮肤癌"],"answer":2,"explanation":"EB病毒与鼻咽癌、Burkitt淋巴瘤相关。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1498","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"与肝癌发生关系最密切的病毒是？","options":["人乳头瘤病毒","EB病毒","乙型肝炎病毒","单纯疱疹病毒"],"answer":2,"explanation":"HBV慢性感染是肝细胞癌的主要危险因素。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1499","_shard":"qk-yiliao-02"},{"module":"yiliao","prompt":"与宫颈癌关系最密切的病原是？","options":["HBV","EB病毒","高危型人乳头瘤病毒（HPV）","HIV"],"answer":2,"explanation":"HPV16、18型等高危型感染是宫颈癌主要病因。","exam":"医疗编","__sub":"病理与药理","diff":1,"id":"yl-1500","_shard":"qk-yiliao-02"}]);